/* CURIOID project modules. Everything runs locally in the visitor's browser. */
(() => {
  'use strict';

  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rand = (a, b) => a + Math.random() * (b - a);
  const pick = a => a[Math.floor(Math.random() * a.length)];
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const uid = () => Math.random().toString(36).slice(2, 9);
  const palettes = {
    mineral: ['#d6ff69','#baa7ff','#ff9cba','#85e6da','#f0d7a8'],
    bruise: ['#25243d','#7d638a','#cc8396','#d6b1a0','#d6ff69'],
    dusk: ['#f0a36f','#9e7bb8','#4f647e','#c7c6af','#e6d7bd'],
    sterile: ['#e6eadf','#9eb4a8','#b6a5c7','#d9b8b3','#5c6660'],
    signal: ['#d6ff69','#ff6d6d','#65d4ff','#baa7ff','#f6f0e6'],
    deep: ['#111827','#263a53','#5d628f','#b09abd','#e8b6a8']
  };

  function downloadBlob(blob, name) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = name;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1500);
  }
  function saveCanvas(canvas, name) {
    try { canvas.toBlob(blob => { if (blob) downloadBlob(blob, name); }, 'image/png'); }
    catch (e) { console.error(e); }
  }
  function fitCanvas(canvas, painter, animate = false) {
    const prefersReducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    animate = Boolean(animate && !prefersReducedMotion);
    const ctx = canvas.getContext('2d', { alpha: false });
    let w = 1, h = 1, dpr = 1, raf = 0, stopped = false, last = 0;
    function resize() {
      const rect = canvas.getBoundingClientRect();
      w = Math.max(1, rect.width); h = Math.max(1, rect.height);
      dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      painter(ctx, w, h, performance.now() / 1000, 0, true);
    }
    const ro = 'ResizeObserver' in window ? new ResizeObserver(resize) : null;
    if (ro) ro.observe(canvas); else window.addEventListener('resize', resize);
    resize();
    function frame(now) {
      if (stopped || document.hidden) { raf = 0; last = 0; return; }
      const dt = Math.min(.04, (now - (last || now)) / 1000); last = now;
      painter(ctx, w, h, now / 1000, dt, false);
      raf = requestAnimationFrame(frame);
    }
    function onVisibilityChange() {
      if (!animate || stopped) return;
      if (document.hidden) {
        if (raf) cancelAnimationFrame(raf);
        raf = 0; last = 0;
      } else if (!raf) {
        last = 0;
        raf = requestAnimationFrame(frame);
      }
    }
    if (animate) {
      document.addEventListener('visibilitychange', onVisibilityChange);
      if (!document.hidden) raf = requestAnimationFrame(frame);
    }
    return {
      ctx, get w(){return w;}, get h(){return h;}, redraw(){painter(ctx,w,h,performance.now()/1000,0,true);},
      stop(){stopped = true; if (raf) cancelAnimationFrame(raf); if (animate) document.removeEventListener('visibilitychange', onVisibilityChange); if (ro) ro.disconnect(); else window.removeEventListener('resize', resize);},
      start(){if (!stopped) return; stopped=false; last=0; if (animate) { document.addEventListener('visibilitychange', onVisibilityChange); if (!document.hidden) raf=requestAnimationFrame(frame); }}
    };
  }
  function toast(api, msg) { if (api && api.toast) api.toast(msg); }
  function projectFrame(kicker, title, description, stage, controls, foot = '') {
    return `<div class="project-tool" data-project-tool><div class="tool-intro"><div><p class="tool-eyebrow">${kicker}</p><h3>${title}</h3><p>${description}</p></div><span class="tool-status">LOCAL / INTERACTIVE</span></div><div class="project-utility" role="toolbar" aria-label="Project controls"><span class="project-utility-note" data-project-save-state>AUTO-SAVE ON THIS DEVICE</span><div class="project-utility-actions"><button type="button" class="project-utility-button" data-project-focus aria-pressed="false">Focus view</button><button type="button" class="project-utility-button" data-project-reset>Reset controls</button></div></div><div class="tool-layout"><section class="tool-main">${stage}${foot ? `<div class="tool-footnote">${foot}</div>` : ''}</section><aside class="tool-controls">${controls}</aside></div></div>`;
  }
  function panel(title, body, extra = '') { return `<section class="tool-panel"><header class="tool-panel-head"><h4>${title}</h4>${extra}</header><div class="tool-panel-body">${body}</div></section>`; }
  function range(label, name, min, max, value, unit = '') { return `<label class="tool-control"><span>${label}<output data-out="${name}">${value}${unit}</output></span><input type="range" data-range="${name}" min="${min}" max="${max}" value="${value}"><small class="tool-help">Adjust the ${label.toLowerCase()}.</small></label>`; }
  function select(label, name, options) { return `<label class="tool-control"><span>${label}</span><select data-select="${name}">${options.map(o=>`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select></label>`; }
  function action(label, name, primary = false) { return `<button type="button" class="tool-button${primary?' primary':''}" data-action="${name}">${label}</button>`; }
  function preferenceKey(control, index) {
    if (control.dataset.range) return `range:${control.dataset.range}`;
    if (control.dataset.select) return `select:${control.dataset.select}`;
    if (control.id) return `id:${control.id}`;
    if (control.name) return `name:${control.name}`;
    return `control:${index}`;
  }
  function projectControls(root) {
    return $$('input:not([type=\"file\"]), select, textarea', root).filter(el => !el.closest('[data-transient-controls]'));
  }
  function restoreProjectPreferences(root, id) {
    let saved = {};
    try { saved = JSON.parse(localStorage.getItem(`curioid-project-preferences-v2:${id}`) || '{}') || {}; } catch (_) {}
    projectControls(root).forEach((control, index) => {
      const key = preferenceKey(control, index);
      if (!(key in saved)) return;
      if (control.type === 'checkbox' || control.type === 'radio') control.checked = Boolean(saved[key]);
      else control.value = String(saved[key]);
    });
  }
  function bindProjectUtilities(root, id, api = {}) {
    const tool = $('[data-project-tool]', root);
    if (!tool) return () => {};
    const saveState = $('[data-project-save-state]', tool);
    const storageKey = `curioid-project-preferences-v2:${id}`;
    let saveTimer = 0;
    function savePreferences() {
      const values = {};
      projectControls(root).forEach((control, index) => {
        if (control.type === 'file' || control.disabled) return;
        values[preferenceKey(control, index)] = control.type === 'checkbox' || control.type === 'radio' ? control.checked : control.value;
      });
      try {
        localStorage.setItem(storageKey, JSON.stringify(values));
        if (saveState) saveState.textContent = 'SETTINGS SAVED LOCALLY';
      } catch (_) {
        if (saveState) saveState.textContent = 'SESSION SETTINGS ONLY';
      }
    }
    const scheduleSave = () => {
      clearTimeout(saveTimer);
      if (saveState) saveState.textContent = 'SAVING SETTINGS…';
      saveTimer = setTimeout(savePreferences, 320);
    };
    const onChange = event => {
      if (event.target.matches('input:not([type=\"file\"]), select, textarea')) scheduleSave();
    };
    root.addEventListener('input', onChange);
    root.addEventListener('change', onChange);

    const focusButton = $('[data-project-focus]', tool);
    focusButton?.addEventListener('click', () => {
      const focused = tool.classList.toggle('project-focus-mode');
      focusButton.setAttribute('aria-pressed', String(focused));
      focusButton.textContent = focused ? 'Exit focus' : 'Focus view';
      if (focused) tool.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });

    const resetButton = $('[data-project-reset]', tool);
    resetButton?.addEventListener('click', () => {
      projectControls(root).forEach(control => {
        if (control.type === 'checkbox' || control.type === 'radio') control.checked = control.defaultChecked;
        else if (control.tagName === 'SELECT') {
          const defaultOption = [...control.options].find(option => option.defaultSelected) || control.options[0];
          if (defaultOption) control.value = defaultOption.value;
        } else control.value = control.defaultValue;
        control.dispatchEvent(new Event('input', { bubbles: true }));
        control.dispatchEvent(new Event('change', { bubbles: true }));
      });
      // Clear the saved snapshot so the next visit starts from the shipped defaults.
      try { localStorage.removeItem(storageKey); } catch (_) {}
      if (saveState) saveState.textContent = 'DEFAULT SETTINGS RESTORED';
      if (api.toast) api.toast('Project controls restored to their defaults.');
    });
    savePreferences();
    return () => {
      clearTimeout(saveTimer);
      root.removeEventListener('input', onChange);
      root.removeEventListener('change', onChange);
    };
  }
  function bindRanges(root) {
    $$('[data-range]', root).forEach(input => {
      const update = () => {
        const out = $(`[data-out=\"${input.dataset.range}\"]`, root);
        if (out) out.textContent = `${input.value}${input.dataset.unit || ''}`;
      };
      input.addEventListener('input', update);
      update();
    });
  }

  // 02 — Gravity Garden: a small softened n-body toy, with draggable bodies.
  function gravityMarkup() {
    return projectFrame('Web experiment / 02', 'Gravity Garden', 'A small universe with a very local idea of gravity. Add bodies, disturb their paths, and see whether the system settles into something beautiful.', `<div class="tool-canvas-wrap"><canvas class="tool-canvas gravity-canvas" aria-label="Gravity simulation"></canvas><div class="canvas-overlay"><span>DRAG A BODY · TAP EMPTY SPACE TO ADD</span><span data-stat="gravity">STABLE ENOUGH</span></div></div><div class="tool-button-row">${action('＋ Add planet','add-planet',true)}${action('Ⅱ Pause','pause-gravity')}${action('↺ Reset system','reset-gravity')}${action('Clear trails','clear-trails')}</div>`, panel('Field settings', range('Gravity','gravity',25,220,105,'%')+range('Orbital speed','speed',35,180,100,'%')+range('Trail length','trail',5,95,55,'%')+`<div class="tool-readout"><span>Objects in the field</span><strong data-stat="bodies">06</strong></div><p class="tool-small">Drag a planet to move it. Tap empty space or use “Add planet” to introduce a body. Drag any planet to change its path. The central object stays fixed; the smaller bodies influence one another. A maximum of 18 bodies keeps the simulation smooth.</p>`), 'A deliberately simplified 2D gravitational model with softening near close approaches. It is a sandbox, not an astrophysics simulator.');
  }
  function bindGravity(root) {
    const canvas = $('.gravity-canvas', root), stat = $('[data-stat="bodies"]', root), state = $('[data-stat="gravity"]', root);
    let bodies = [], paused = false, drag = null, trail = 55, gravity = 105, speed = 100, lastW = 1, lastH = 1;
    const reset = () => {
      bodies = [{x:.5,y:.5,vx:0,vy:0,m:34,r:17,c:'#d6ff69',fixed:true,trail:[]},
        ...[0,1,2,3,4].map((i)=>{const a=i*1.256+rand(-.2,.2),r=.15+i*.045, v=Math.sqrt(0.45/r)*(speed/100);return{x:.5+Math.cos(a)*r,y:.5+Math.sin(a)*r,vx:-Math.sin(a)*v,vy:Math.cos(a)*v,m:rand(2,8),r:rand(4,8),c:pick(palettes.mineral),trail:[]};})];
      stat.textContent=bodies.length; sim.redraw();
    };
    let sim = fitCanvas(canvas, (ctx,w,h,t,dt,initial) => {
      lastW=w; lastH=h;
      ctx.fillStyle='#10131a'; ctx.fillRect(0,0,w,h);
      ctx.strokeStyle='rgba(214,255,105,.055)'; ctx.lineWidth=1;
      for(let x=0;x<w;x+=32){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke();}
      for(let y=0;y<h;y+=32){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}
      if(!initial && !paused && dt>0){
        const g=gravity/100*240, soft=18, step=Math.min(.022,dt)*speed/100;
        for(let i=1;i<bodies.length;i++){
          const b=bodies[i]; let ax=0,ay=0;
          for(let j=0;j<bodies.length;j++){if(i===j)continue;const a=bodies[j],dx=(a.x-b.x)*w,dy=(a.y-b.y)*h,d2=dx*dx+dy*dy+soft*soft,inv=1/Math.pow(d2,1.5);ax+=g*a.m*dx*inv;ay+=g*a.m*dy*inv;}
          b.vx+=ax*step; b.vy+=ay*step;
        }
        for(let i=1;i<bodies.length;i++){const b=bodies[i];b.x+=b.vx*step/w;b.y+=b.vy*step/h;b.trail.push([b.x*w,b.y*h]);if(b.trail.length>Math.round(18+trail*1.5))b.trail.shift();if(b.x<.03||b.x>.97)b.vx*=-.94;if(b.y<.05||b.y>.95)b.vy*=-.94;b.x=clamp(b.x,.03,.97);b.y=clamp(b.y,.05,.95);}
      }
      bodies.forEach((b,i)=>{
        if(b.trail.length>1){ctx.beginPath();b.trail.forEach((p,j)=>j?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.strokeStyle=b.c+'88';ctx.lineWidth=Math.max(1,b.r*.34);ctx.stroke();}
        const x=b.x*w,y=b.y*h; const glow=ctx.createRadialGradient(x,y,1,x,y,b.r*(i===0?3.7:2.5));glow.addColorStop(0,b.c+'88');glow.addColorStop(1,b.c+'00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(x,y,b.r*(i===0?3.7:2.5),0,Math.PI*2);ctx.fill();ctx.fillStyle=b.c;ctx.beginPath();ctx.arc(x,y,b.r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff8';ctx.lineWidth=1;ctx.stroke();
      });
      if(!initial){state.textContent=paused?'FIELD PAUSED':'FIELD ACTIVE';}
    }, true);
    reset();
    const onRange = (key, fn) => {const el=$(`[data-range="${key}"]`,root);el.addEventListener('input',()=>fn(Number(el.value)));};
    onRange('gravity',v=>gravity=v);onRange('speed',v=>speed=v);onRange('trail',v=>trail=v);
    function addBodyAt(point){
      if(bodies.length>=18){toast(null,'The field is full. Remove bodies by resetting the system.');return;}
      const dx=point.x-.5,dy=point.y-.5,r=Math.max(.08,Math.hypot(dx,dy)),a=Math.atan2(dy,dx),v=Math.sqrt(.45/r)*speed/100;
      bodies.push({x:clamp(point.x,.05,.95),y:clamp(point.y,.07,.93),vx:-Math.sin(a)*v,vy:Math.cos(a)*v,m:rand(2,9),r:rand(4,8),c:pick(palettes.mineral),trail:[]});
      stat.textContent=bodies.length;sim.redraw();toast(null,'A new body entered the field.');
    }
    $('[data-action="add-planet"]',root).addEventListener('click',()=>{const a=rand(0,Math.PI*2),r=rand(.17,.43);addBodyAt({x:.5+Math.cos(a)*r,y:.5+Math.sin(a)*r});});
    $('[data-action="pause-gravity"]',root).addEventListener('click',e=>{paused=!paused;e.currentTarget.textContent=paused?'▶ Resume':'Ⅱ Pause';state.textContent=paused?'FIELD PAUSED':'FIELD ACTIVE';});
    $('[data-action="reset-gravity"]',root).addEventListener('click',reset);
    $('[data-action="clear-trails"]',root).addEventListener('click',()=>bodies.forEach(b=>b.trail=[]));
    function pos(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height};}
    canvas.addEventListener('pointerdown',e=>{const p=pos(e);let best=null,dist=1e9;bodies.slice(1).forEach(b=>{const d=Math.hypot((b.x-p.x)*lastW,(b.y-p.y)*lastH);if(d<dist){dist=d;best=b;}});if(best&&dist<24){drag=best;canvas.setPointerCapture(e.pointerId);}else if(Math.hypot((.5-p.x)*lastW,(.5-p.y)*lastH)>30){addBodyAt(p);}});
    canvas.addEventListener('pointermove',e=>{if(!drag)return;const p=pos(e);drag.x=clamp(p.x,.04,.96);drag.y=clamp(p.y,.06,.94);drag.vx=0;drag.vy=0;drag.trail=[];});
    const end=()=>drag=null;canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);
    return ()=>sim.stop();
  }

  // 03 — Pattern Engine: radial geometry with coherent symmetry and export.
  function patternMarkup(){return projectFrame('Web experiment / 03','Pattern Engine','Build a visual system, then keep turning the dial until its symmetry starts to feel less certain.',`<div class="tool-canvas-wrap art-canvas-wrap"><canvas class="tool-canvas pattern-canvas" aria-label="Generated geometric pattern"></canvas><div class="canvas-overlay"><span>GENERATIVE STUDY</span><span data-pattern-seed>SEED 0001</span></div></div><div class="tool-button-row">${action('↻ New pattern','new-pattern',true)}${action('Copy seed','copy-pattern-seed')}${action('↓ Export PNG','export-pattern')}</div>`,panel('Pattern controls',select('Geometry','geometry',[['mixed','Mixed geometry'],['petal','Petal field'],['orbit','Orbit marks'],['shard','Broken shards'],['rings','Nested rings']])+range('Symmetry','symmetry',3,18,9)+range('Density','density',8,70,34)+range('Distortion','distortion',0,100,42)+select('Palette','palette',[['mineral','Mineral study'],['bruise','Bruised velvet'],['dusk','Last light'],['sterile','Quiet laboratory'],['signal','Signal error']])+`<label class="tool-control"><span>Recreate a seed</span><input type="number" data-pattern-seed-input min=0 max=999999 step=1 value=1></label><div class="tool-button-row">${action('Apply seed','apply-pattern-seed')}</div><p class="tool-small">Copy a seed to recreate the exact same composition later. Export saves the current frame as a PNG.</p>`),'The image is generated with canvas primitives and deterministic layout choices; no artwork is uploaded or fetched.');}
  function bindPattern(root){const canvas=$('.pattern-canvas',root);let seed=Math.random()*1e6;function draw(){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;const dpr=window.devicePixelRatio||1;const W=canvas.clientWidth,H=canvas.clientHeight;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#10131a';ctx.fillRect(0,0,W,H);const p=palettes[$('[data-select="palette"]',root).value]||palettes.mineral;const symmetry=Number($('[data-range="symmetry"]',root).value),density=Number($('[data-range="density"]',root).value),dist=Number($('[data-range="distortion"]',root).value)/100,geometry=$('[data-select="geometry"]',root).value;let s=seed;const rr=()=>{s=(s*1664525+1013904223)%4294967296;return s/4294967296;};const cx=W/2,cy=H/2,R=Math.min(W,H)*.39;ctx.save();ctx.translate(cx,cy);for(let i=0;i<symmetry;i++){ctx.save();ctx.rotate(i*Math.PI*2/symmetry);for(let j=0;j<density;j++){const radius=R*(.12+j/density*.88),a=rr()*Math.PI*2, offset=(rr()-.5)*dist*R*.36, size=R*(.012+rr()*.055)*(1+dist);ctx.save();ctx.rotate(a*.18);ctx.translate(offset,radius);ctx.globalAlpha=.26+rr()*.65;ctx.strokeStyle=pick(p);ctx.fillStyle=pick(p);ctx.lineWidth=1+rr()*3;if(geometry==='rings'||(geometry==='mixed'&&j%4===0)){ctx.beginPath();ctx.arc(0,0,size*(1+rr()*2),0,Math.PI*2);ctx.stroke();}else if(geometry==='petal'||(geometry==='mixed'&&j%3===0)){ctx.beginPath();ctx.ellipse(0,0,size*.5,size*(1.2+rr()*3),0,0,Math.PI*2);ctx.fill();}else if(geometry==='orbit'){ctx.beginPath();ctx.moveTo(-size*2,0);ctx.quadraticCurveTo(0,-size*3,size*2,0);ctx.stroke();}else{ctx.beginPath();ctx.moveTo(-size,0);ctx.lineTo(0,-size*2);ctx.lineTo(size,0);ctx.lineTo(0,size*2);ctx.closePath();ctx.fill();}ctx.restore();}ctx.restore();}ctx.restore();const g=ctx.createRadialGradient(cx,cy,0,cx,cy,R*.5);g.addColorStop(0,'rgba(16,19,26,.03)');g.addColorStop(1,'rgba(16,19,26,.76)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);}
    const obs=fitCanvas(canvas,()=>draw(),false);const seedField=$('[data-pattern-seed-input]',root);const applySeed=value=>{seed=Math.max(0,Math.min(999999,Math.floor(Number(value)||0)));seedField.value=String(seed);$('[data-pattern-seed]',root).textContent='SEED '+String(seed).padStart(6,'0');obs.redraw();};const update=()=>applySeed(Math.floor(Math.random()*999999));
    $('[data-action="new-pattern"]',root).addEventListener('click',update);$('[data-action="apply-pattern-seed"]',root).addEventListener('click',()=>applySeed(seedField.value));seedField.addEventListener('change',()=>applySeed(seedField.value));seedField.addEventListener('keydown',e=>{if(e.key==='Enter')applySeed(seedField.value);});$('[data-action="copy-pattern-seed"]',root).addEventListener('click',async()=>{const text=String(seed).padStart(6,'0');try{await navigator.clipboard.writeText(text);toast(null,'Pattern seed copied.');}catch(e){downloadBlob(new Blob([text],{type:'text/plain'}),'curioid-pattern-seed.txt');}});['symmetry','density','distortion'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',()=>obs.redraw()));$('[data-select="geometry"]',root).addEventListener('change',()=>obs.redraw());$('[data-select="palette"]',root).addEventListener('change',()=>obs.redraw());$('[data-action="export-pattern"]',root).addEventListener('click',()=>saveCanvas(canvas,'curioid-pattern.png'));applySeed(seedField.value || Math.floor(Math.random()*999999));return()=>obs.stop();}

  // 04 — Echo Cabinet: an explicit, user-started three-lane step sequencer.
  function echoMarkup(){const tracks=['LOW','MID','HIGH'];return projectFrame('Web experiment / 04','Echo Cabinet','A little sequencer for sounds that are not sure what room they belong in. Place a few notes, set the pace, and let the pattern repeat.',`<div class="sequencer-shell"><div class="sequencer-top"><span>16-STEP MEMORY</span><span data-seq-step>STEP 01 / 16</span></div><div class="sequencer-grid">${tracks.map((t,r)=>`<div class="seq-row"><span class="seq-track">${t}</span>${Array.from({length:16},(_,i)=>`<button class="seq-cell${[0,4,8,12].includes(i)?' beat':''}${(i+r*3)%7===0?' on':''}" type="button" data-track="${r}" data-step="${i}" aria-label="${t} step ${i+1}" aria-pressed="${(i+r*3)%7===0}"></button>`).join('')}</div>`).join('')}</div><div class="seq-leds">${Array.from({length:16},(_,i)=>`<i data-led="${i}"></i>`).join('')}</div></div><div class="tool-button-row">${action('▶ Play sequence','play-echo',true)}${action('■ Stop','stop-echo')}${action('Randomize','random-echo')}${action('Clear steps','clear-echo')}</div>`,panel('Sequence settings',range('Tempo','tempo',55,170,104,' BPM')+range('Echo / delay','echo',0,80,22,'%')+range('Dissonance','dissonance',0,100,28,'%')+select('Tone family','tone',[['glass','Glass room'],['wood','Warm machine'],['wire','Thin wire'],['hollow','Hollow bell']])+`<p class="tool-small">Audio begins only after you press Play. Your browser may ask permission to start audio after the first interaction.</p>`),'Web Audio runs on-device. The sequencer creates its tones in real time and does not play or upload recorded music.');}
  function bindEcho(root){let ac=null,master=null,timer=null,playing=false,step=0,next=0;const patternKey='curioid-echo-cabinet-pattern-v1';const patterns=Array.from({length:3},(_,r)=>Array.from({length:16},(_,i)=>(i+r*3)%7===0));const cells=$$('.seq-cell',root);const tempo=$('[data-range="tempo"]',root),echo=$('[data-range="echo"]',root),dissonance=$('[data-range="dissonance"]',root);try{const stored=JSON.parse(localStorage.getItem(patternKey)||'null');if(Array.isArray(stored)&&stored.length===3&&stored.every(row=>Array.isArray(row)&&row.length===16))stored.forEach((row,i)=>row.forEach((v,j)=>patterns[i][j]=Boolean(v)));}catch(_){}function persistPattern(){try{localStorage.setItem(patternKey,JSON.stringify(patterns));}catch(_){}}function setCell(c,on,save=true){c.classList.toggle('on',on);c.setAttribute('aria-pressed',String(on));patterns[+c.dataset.track][+c.dataset.step]=on;if(save)persistPattern();}
    cells.forEach(c=>{setCell(c,patterns[+c.dataset.track][+c.dataset.step],false);c.addEventListener('click',()=>setCell(c,!patterns[+c.dataset.track][+c.dataset.step]));});
    function ensureAudio(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC){toast(null,'Web Audio is not available in this browser.');return false;}if(!ac){ac=new AC();master=ac.createGain();master.gain.value=.42;master.connect(ac.destination);}if(ac.state==='suspended')ac.resume();return true;}
    function note(track,time){const freqs=[55,110,220,330,440,660];const base=freqs[(step+track*2)%freqs.length];const detune=1+Number(dissonance.value)/100*.022*Math.sin(step*2.2+track);const osc=ac.createOscillator(),gain=ac.createGain(),filter=ac.createBiquadFilter(),delay=ac.createDelay(.45),feedback=ac.createGain();const types=['sine','triangle','square'];const tone=$('[data-select="tone"]',root).value;osc.type=tone==='wire'?'sawtooth':tone==='wood'?'triangle':tone==='hollow'?'sine':types[track];osc.frequency.setValueAtTime(base*(track===1?2:track===2?4:1)*detune,time);filter.type='lowpass';filter.frequency.value=tone==='wire'?1200:tone==='wood'?700:tone==='hollow'?1800:2600;gain.gain.setValueAtTime(.0001,time);gain.gain.exponentialRampToValueAtTime(track===0?.45:.2,time+.012);gain.gain.exponentialRampToValueAtTime(.0001,time+.18);delay.delayTime.value=.11;feedback.gain.value=Number(echo.value)/100*.5;osc.connect(filter);filter.connect(gain);gain.connect(master);gain.connect(delay);delay.connect(feedback);feedback.connect(delay);delay.connect(master);osc.start(time);osc.stop(time+.22);}
    function scheduler(){while(next<ac.currentTime+.12){patterns.forEach((p,r)=>{if(p[step])note(r,next);});const led=$(`[data-led="${step}"]`,root);if(led){$$('[data-led]',root).forEach(x=>x.classList.remove('active'));led.classList.add('active');}$('[data-seq-step]',root).textContent=`STEP ${String(step+1).padStart(2,'0')} / 16`;step=(step+1)%16;next+=60/Number(tempo.value)/4;}}
    function play(){if(!ensureAudio())return;playing=true;step=0;next=ac.currentTime+.06;timer=setInterval(scheduler,25);$('[data-action="play-echo"]',root).textContent='● Playing';}
    function stop(){playing=false;if(timer)clearInterval(timer);timer=null;$$('[data-led]',root).forEach(x=>x.classList.remove('active'));$('[data-action="play-echo"]',root).textContent='▶ Play sequence';}
    $('[data-action="play-echo"]',root).addEventListener('click',()=>{if(playing)stop();else play();});$('[data-action="stop-echo"]',root).addEventListener('click',stop);$('[data-action="random-echo"]',root).addEventListener('click',()=>{cells.forEach(c=>setCell(c,Math.random()<([.2,.31,.17][+c.dataset.track])));});$('[data-action="clear-echo"]',root).addEventListener('click',()=>{cells.forEach(c=>setCell(c,false));toast(null,'The sequence has been cleared.');});
    return()=>{stop();if(ac)ac.close().catch(()=>{});};}

  // 05 — Impossible Objects: three visual paradox studies with viewpoint control.
  function impossibleMarkup(){return projectFrame('Web experiment / 05','Impossible Objects','A small inspection table for structures that seem to agree with themselves until you follow one edge too far.',`<div class="tool-canvas-wrap paradox-wrap"><canvas class="tool-canvas paradox-canvas" aria-label="Impossible geometry illustration"></canvas><div class="canvas-overlay"><span>DRAG TO ROTATE</span><span data-paradox-label>PENROSE LOOP</span></div></div><div class="tool-button-row">${action('↻ Change viewpoint','paradox-view',true)}${action('＋ Next structure','paradox-next')}${action('↓ Export PNG','paradox-export')}</div>`,panel('Inspection controls',select('Structure','paradox-shape',[['triangle','Penrose loop'],['stairs','Returning staircase'],['fork','Three-way fork']])+range('Perspective','perspective',0,100,48)+`<label class="tool-check"><input type="checkbox" data-paradox-seams checked> Show construction seams</label><p class="tool-small">Try following one continuous edge. The diagram will not help you.</p>`),'The structures are illustrative optical constructions, not physically buildable objects.');}
  function bindImpossible(root){const canvas=$('.paradox-canvas',root);let angle=0;function paint(ctx,w,h){ctx.fillStyle='#11131a';ctx.fillRect(0,0,w,h);const cx=w/2,cy=h/2,scale=Math.min(w,h)*.0042,mode=$('[data-select="paradox-shape"]',root).value,per=Number($('[data-range="perspective"]',root).value)/100,seams=$('[data-paradox-seams]',root).checked;ctx.save();ctx.translate(cx,cy);ctx.rotate(angle);ctx.scale(scale,scale);ctx.lineJoin='round';ctx.lineCap='round';
      const poly=(pts,fill,stroke='#101015',lw=8)=>{ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle=stroke;ctx.lineWidth=lw;ctx.stroke();};
      if(mode==='triangle'){
        const A=[0,-170],B=[185,150],C=[-185,150],inner=[0,22];
        poly([[A[0],A[1]],[A[0]-43,A[1]+74],[inner[0]-42,inner[1]-5],[inner[0],inner[1]-70]],'#d6ff69');
        poly([[A[0],A[1]],[A[0]+43,A[1]+74],[inner[0]+42,inner[1]-5],[inner[0],inner[1]-70]],'#a7cc48');
        poly([[A[0]-43,A[1]+74],[C[0]+42,C[1]-73],[C[0]+42,C[1]-25],[inner[0]-42,inner[1]-5]],'#8aab4c');
        poly([[C[0],C[1]],[C[0]+84,C[1]],[inner[0]+42,inner[1]+42],[inner[0]-42,inner[1]+42]],'#d6ff69');
        poly([[B[0],B[1]],[B[0]-84,B[1]],[inner[0]+42,inner[1]-5],[inner[0]+42,inner[1]+42]],'#baa7ff');
        poly([[A[0]+43,A[1]+74],[B[0]-42,B[1]-73],[B[0]-42,B[1]-25],[inner[0]+42,inner[1]-5]],'#8c78ce');
        if(seams){ctx.strokeStyle='#f1f0ed';ctx.globalAlpha=.6;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-142,80);ctx.lineTo(-92,52);ctx.moveTo(142,80);ctx.lineTo(92,52);ctx.moveTo(0,-93);ctx.lineTo(0,-48);ctx.stroke();ctx.globalAlpha=1;}
      } else if(mode==='stairs'){
        for(let i=0;i<10;i++){const a=i*Math.PI/5+per*.45;const r=65+i*11;const x=Math.cos(a)*r,y=Math.sin(a)*r;ctx.save();ctx.translate(x,y);ctx.rotate(a+Math.PI/2);poly([[-31,-13],[31,-13],[42,0],[-20,0]],i%2?'#baa7ff':'#d6ff69');poly([[-20,0],[42,0],[42,18],[-20,18]],i%2?'#806eb1':'#879e45');ctx.restore();}ctx.strokeStyle='#e2d5b2';ctx.lineWidth=12;ctx.beginPath();ctx.arc(0,0,148,Math.PI*.15,Math.PI*1.82);ctx.stroke();ctx.strokeStyle='#11131a';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,148,Math.PI*.15,Math.PI*1.82);ctx.stroke();
      } else {
        poly([[-150,-120],[-80,-120],[-10,-15],[-82,85],[-150,85],[-68,-15]],'#d6ff69');poly([[-10,-15],[90,-150],[160,-150],[35,-15],[90,100],[20,100]],'#baa7ff');poly([[20,100],[90,100],[160,180],[90,180]],'#806eb1');poly([[-150,85],[-82,85],[-30,170],[-100,170]],'#93af54');if(seams){ctx.strokeStyle='#f7f0df';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-80,-110);ctx.lineTo(-12,-10);ctx.lineTo(88,-145);ctx.stroke();}}
      ctx.restore();ctx.fillStyle='#7f7d8a';ctx.font='10px ui-monospace,monospace';ctx.textAlign='center';ctx.fillText('FOLLOW THE EDGE. DO NOT BLINK.',w/2,h-20);
    }
    const sim=fitCanvas(canvas,(ctx,w,h)=>paint(ctx,w,h),false);function redraw(){const names={triangle:'PENROSE LOOP',stairs:'RETURNING STAIRCASE',fork:'THREE-WAY FORK'};$('[data-paradox-label]',root).textContent=names[$('[data-select="paradox-shape"]',root).value];sim.redraw();}
    let dragX=null;canvas.style.cursor='grab';canvas.addEventListener('pointerdown',e=>{dragX=e.clientX;canvas.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing';});canvas.addEventListener('pointermove',e=>{if(dragX===null)return;angle+=(e.clientX-dragX)*.012;dragX=e.clientX;redraw();});const endDrag=()=>{dragX=null;canvas.style.cursor='grab';};canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);$('[data-action="paradox-view"]',root).addEventListener('click',()=>{angle+=Math.PI/6;redraw();});$('[data-action="paradox-next"]',root).addEventListener('click',()=>{const s=$('[data-select="paradox-shape"]',root),v=['triangle','stairs','fork'];s.value=v[(v.indexOf(s.value)+1)%v.length];angle=0;redraw();});$('[data-action="paradox-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'impossible-object.png'));$('[data-select="paradox-shape"]',root).addEventListener('change',redraw);$('[data-range="perspective"]',root).addEventListener('input',redraw);$('[data-paradox-seams]',root).addEventListener('change',redraw);redraw();return()=>sim.stop();}

  // 06 — Pixel Weather: a small animated climate generator.
  function weatherMarkup(){return projectFrame('Web experiment / 06','Pixel Weather','Forecasts from places that do not appear on maps. Change the atmosphere, wait for it to move, and watch the climate settle into its own habits.',`<div class="tool-canvas-wrap"><canvas class="tool-canvas weather-canvas" aria-label="Animated fictional weather"></canvas><div class="canvas-overlay"><span data-weather-place>THE GLASS COAST</span><span data-weather-state>LOCAL CONDITIONS</span></div></div><div class="tool-button-row">${action('↻ New forecast','weather-new',true)}${action('Ⅱ Pause sky','weather-pause')}${action('↓ Save forecast','weather-export')}</div>`,panel('Atmosphere',select('Climate','climate',[['glass','Glass rain'],['ember','Emberfall'],['violet','Violet heat'],['quiet','Quiet snow'],['dust','Dust tide']])+range('Wind','wind',0,100,48)+range('Cloud cover','cloud',0,100,55)+range('Oddness','weather-odd',0,100,62)+`<p class="tool-small">Every forecast is generated locally. The climate may look calm, but it is not necessarily stable.</p>`),'Canvas animation pauses when the project closes; it does not continue running in the background.');}
  function bindWeather(root){const canvas=$('.weather-canvas',root);let particles=[],paused=false,climate='glass',wind=48,cloud=55,odd=62,seed=0,lightning=0;const placeNames=['THE GLASS COAST','NORTH OF THE LAST HOUR','THE QUIET EQUATOR','LOWER BLUE DISTRICT','THE WARMING ROOM','SALT ORCHARD'];function forecast(){seed++;particles=Array.from({length:150},()=>({x:Math.random(),y:Math.random(),v:rand(.12,.8),s:rand(1,4),phase:rand(0,8)}));climate=$('[data-select="climate"]',root).value;wind=+$('[data-range="wind"]',root).value;cloud=+$('[data-range="cloud"]',root).value;odd=+$('[data-range="weather-odd"]',root).value;$('[data-weather-place]',root).textContent=pick(placeNames);$('[data-weather-state]',root).textContent=climate.toUpperCase()+' / '+Math.round(rand(3,27))+'°';sim.redraw();}
    const sim=fitCanvas(canvas,(ctx,w,h,t,dt,initial)=>{if(!paused&&!initial){particles.forEach(p=>{p.y+=p.v*(climate==='glass'?1.4:.55)*dt;p.x+=Math.sin(t+p.phase)*dt*(wind/100)*.14;if(p.y>1.05){p.y=-.04;p.x=Math.random();}if(p.x>1)p.x=0;if(p.x<0)p.x=1;});if(Math.random()<dt*(odd/100)*.07)lightning=.12;lightning=Math.max(0,lightning-dt);}
      const themes={glass:['#14273a','#547d91','#b6dcdb'],ember:['#221921','#6b3c47','#e0a06e'],violet:['#28213d','#76618e','#efa0b2'],quiet:['#222c36','#667a8e','#d8e7e8'],dust:['#302923','#8b6d53','#d5bd8c']},c=themes[climate]||themes.glass;const g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,c[0]);g.addColorStop(.7,c[1]);g.addColorStop(1,'#11141b');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
      const sunX=w*(climate==='violet'?.72:.2),sunY=h*.3,sunR=Math.min(w,h)*.09;const halo=ctx.createRadialGradient(sunX,sunY,2,sunX,sunY,sunR*3);halo.addColorStop(0,c[2]+'77');halo.addColorStop(1,c[2]+'00');ctx.fillStyle=halo;ctx.fillRect(0,0,w,h);ctx.fillStyle=c[2];ctx.globalAlpha=.75;ctx.beginPath();ctx.arc(sunX,sunY,sunR,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
      const cloudN=Math.round(cloud/9);for(let i=0;i<cloudN;i++){const x=((i*137+Math.sin(t*.05+i)*30)%w),y=h*(.12+(i%4)*.1);ctx.fillStyle=`rgba(12,17,27,${.12+cloud/260})`;ctx.beginPath();ctx.ellipse(x,y,50+(i%3)*22,10+(i%4)*5,0,0,Math.PI*2);ctx.fill();}
      // Horizon silhouettes.
      ctx.fillStyle='#10141a';ctx.beginPath();ctx.moveTo(0,h*.78);for(let x=0;x<=w;x+=30)ctx.lineTo(x,h*(.7+Math.sin(x*.012+seed)*.025+Math.sin(x*.03)*.012));ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();ctx.fill();
      particles.forEach(p=>{const x=p.x*w,y=p.y*h;ctx.strokeStyle=c[2];ctx.fillStyle=c[2];ctx.globalAlpha=.25+p.v*.45;ctx.lineWidth=p.s;if(climate==='glass'){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-wind*.035,y+8+p.v*12);ctx.stroke();}else if(climate==='quiet'){ctx.beginPath();ctx.arc(x,y,p.s*1.3,0,Math.PI*2);ctx.fill();}else if(climate==='ember'){ctx.beginPath();ctx.ellipse(x,y,p.s*.65,p.s*2,Math.sin(t+p.phase),0,Math.PI*2);ctx.fill();}else{ctx.fillRect(x,y,p.s*2,p.s*2);}});ctx.globalAlpha=1;
      if(lightning>0){ctx.fillStyle=`rgba(221,226,255,${lightning*1.2})`;ctx.fillRect(0,0,w,h);ctx.strokeStyle='#e9eaff';ctx.lineWidth=2;ctx.beginPath();let x=w*(.3+Math.random()*.4),y=0;ctx.moveTo(x,y);for(let i=0;i<5;i++){x+=rand(-20,20);y+=h*.12;ctx.lineTo(x,y);}ctx.stroke();}
      ctx.fillStyle=c[2]+'99';ctx.font='9px ui-monospace,monospace';ctx.fillText('ATMOSPHERIC MODEL / '+String(seed).padStart(3,'0'),14,h-14);
    },true);
    forecast();['wind','cloud','weather-odd'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',()=>{wind=+$('[data-range="wind"]',root).value;cloud=+$('[data-range="cloud"]',root).value;odd=+$('[data-range="weather-odd"]',root).value;}));$('[data-select="climate"]',root).addEventListener('change',forecast);$('[data-action="weather-new"]',root).addEventListener('click',forecast);$('[data-action="weather-pause"]',root).addEventListener('click',e=>{paused=!paused;e.currentTarget.textContent=paused?'▶ Resume sky':'Ⅱ Pause sky';});$('[data-action="weather-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'pixel-weather.png'));return()=>sim.stop();}

  // 07 — Dream Index: inspect dream locations and collect their small records.
  const dreams=[
    ['The Hotel With No Lobby','A hotel whose rooms are arranged around a space that the floor plan calls “outside”.','A brass key is warm, although the room has been empty for years.'],
    ['Station 0','The timetable lists destinations by the names of people who have not arrived yet.','A train passes without windows. Every seat is occupied by a folded coat.'],
    ['The Indoor Sea','A tide moves beneath a painted ceiling. The beach is carpeted and always dry.','A lifeguard points at the horizon and asks whether you remember it correctly.'],
    ['The House of Second Windows','Every room has one more window than its exterior could contain.','Behind the smallest window, someone is closing the same curtains.'],
    ['Museum of Unfinished Sounds','Objects are displayed with the noises they almost made.','The little bell has no clapper. Visitors still lower their voices near it.'],
    ['The Warm Stairwell','The stairs go up and down but always return to the same landing.','There are fresh footprints on the ceiling. They are yours, but older.'],
    ['Municipal Cloud Room','A public office where weather is filed, stamped and occasionally misplaced.','The clerk asks you to sign for the fog. The signature is already there.'],
    ['The Orchard Under Glass','Fruit grows in sealed jars, each labelled with a date from next week.','One jar contains a note describing the room you are standing in.']
  ];
  function dreamMarkup(){return projectFrame('Web experiment / 07','Dream Index','An index of places that are almost familiar. Visit a location, inspect its details, and keep the fragments that remain after waking.',`<div class="dream-scene"><div class="dream-scene-art" data-dream-art></div><div class="dream-scene-caption"><span data-dream-index>LOCATION 01 / 08</span><strong data-dream-title>The Hotel With No Lobby</strong></div></div><div class="tool-button-row">${action('← Previous place','dream-prev')}${action('Another place →','dream-next',true)}${action('＋ Keep fragment','dream-keep')}</div><div class="dream-hotspots" data-dream-hotspots></div>`,panel('Your dream record',`<p class="dream-copy" data-dream-copy></p><div class="dream-fragment" data-dream-fragment>Nothing has been recorded yet.</div><div class="tool-readout"><span>Fragments kept</span><strong data-dream-kept>0</strong></div><div class="tool-button-row">${action('Export dream notes','dream-export')}</div><p class="tool-small">This is a fictional index. All locations and fragments are part of the experience.</p>`),'Collected fragments are saved in this browser and can be exported as a text file.');}
  function bindDream(root){let idx=0,kept=[];const storageKey='curioid-dream-index-fragments-v1';try{const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(saved))kept=saved.filter(x=>Array.isArray(x)&&x.length===3).slice(0,8);}catch(_){}const art=$('[data-dream-art]',root),copy=$('[data-dream-copy]',root),fragment=$('[data-dream-fragment]',root),hotspots=$('[data-dream-hotspots]',root);function render(){const d=dreams[idx];$('[data-dream-index]',root).textContent=`LOCATION ${String(idx+1).padStart(2,'0')} / ${String(dreams.length).padStart(2,'0')}`;$('[data-dream-title]',root).textContent=d[0];copy.textContent=d[1];fragment.textContent=d[2];art.innerHTML=`<div class="dream-geometry geom-${idx%4}"><span class="dream-sun"></span><span class="dream-arch"></span><span class="dream-ground"></span><span class="dream-window"></span><span class="dream-door"></span><span class="dream-dust d1"></span><span class="dream-dust d2"></span></div>`;hotspots.innerHTML=['The threshold','A small object','The distant detail'].map((x,i)=>`<button type="button" class="dream-hotspot" data-hot="${i}">${x} <span>↗</span></button>`).join('');$$('[data-hot]',hotspots).forEach((b,i)=>b.addEventListener('click',()=>{fragment.textContent=[d[2],`You notice that ${['the door opens inward, although the corridor is on the other side.','the object is labelled with your initials, in handwriting you do not recognize.','the distant shape moves only when you look away.'][i]}`,d[2]][i];}));}function move(n){idx=(idx+n+dreams.length)%dreams.length;render();} $('[data-action="dream-prev"]',root).addEventListener('click',()=>move(-1));$('[data-action="dream-next"]',root).addEventListener('click',()=>move(1));function updateKept(){$('[data-dream-kept]',root).textContent=kept.length;}function persistKept(){try{localStorage.setItem(storageKey,JSON.stringify(kept));return true;}catch(_){return false;}}$('[data-action="dream-keep"]',root).addEventListener('click',()=>{const d=dreams[idx];if(kept.some(x=>x[0]===d[0])){toast(null,'This fragment is already in your notebook.');return;}kept.push(d);updateKept();toast(null,persistKept()?'Fragment saved in your notebook.':'Fragment kept for this visit; browser storage is unavailable.');});$('[data-action="dream-export"]',root).addEventListener('click',()=>downloadBlob(new Blob([kept.map(d=>`${d[0]}\n${d[1]}\n${d[2]}`).join('\n\n')||'No fragments collected.'],{type:'text/plain'}),'dream-index-notes.txt'));updateKept();render();return()=>{};}

  // 08 — Chromatic Fossils: procedural geological colour composition.
  function chromaticMarkup(){return projectFrame('Digital art / 01','Chromatic Fossils','Excavate a composition from layers of pigment, mineral bands and pressure marks. Each plate is a small geological accident.',`<div class="tool-canvas-wrap art-canvas-wrap"><canvas class="tool-canvas chromatic-canvas" aria-label="Generated chromatic geological artwork"></canvas><div class="canvas-overlay"><span>PLATE / <b data-plate-number>001</b></span><span>FOUND COLOR / FIELD STUDY</span></div></div><div class="tool-button-row">${action('Excavate another plate','fossil-new',true)}${action('↓ Export plate','fossil-export')}</div>`,panel('Excavation settings',select('Material','fossil-palette',[['mineral','Mineral strata'],['bruise','Bruised glass'],['dusk','Twilight sediment'],['sterile','Pale ceramic'],['deep','Deep ocean']])+range('Layer count','layers',4,28,13)+range('Pressure','pressure',0,100,58)+range('Grain','grain',0,100,42)+`<p class="tool-small">The artwork is generated at high pixel density and can be saved as a PNG.</p>`),'Original procedural art. Each new plate uses a fresh composition seed.');}
  function bindChromatic(root){const canvas=$('.chromatic-canvas',root);let seed=1;const sim=fitCanvas(canvas,(ctx,w,h,t,dt,initial)=>{ctx.fillStyle='#11131a';ctx.fillRect(0,0,w,h);let s=seed;const r=()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296;};const p=palettes[$('[data-select="fossil-palette"]',root).value];const layers=+$('[data-range="layers"]',root).value,pressure=+$('[data-range="pressure"]',root).value/100,grain=+$('[data-range="grain"]',root).value/100;ctx.save();ctx.translate(w*.08,h*.05);ctx.scale(.84,.9);for(let i=0;i<layers;i++){const y=h*(.05+i/layers*.82),amp=8+pressure*55,offset=(r()-.5)*50;ctx.beginPath();ctx.moveTo(0,y);for(let x=0;x<=w;x+=5){const yy=y+Math.sin(x*.009+i*.72+seed)*amp+Math.sin(x*.031+i*2.2)*amp*.28+offset;ctx.lineTo(x,yy);}ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();ctx.fillStyle=p[i%p.length];ctx.globalAlpha=.28+r()*.65;ctx.fill();ctx.strokeStyle='#0b0d11';ctx.lineWidth=1+r()*3;ctx.stroke();}ctx.globalAlpha=1;for(let i=0;i<1800*grain;i++){const x=r()*w,y=r()*h;ctx.fillStyle=r()>.5?'#fff':'#090a0e';ctx.globalAlpha=r()*.18;ctx.fillRect(x,y,r()*1.8+.3,r()*1.8+.3);}ctx.restore();ctx.globalAlpha=1;ctx.strokeStyle='rgba(255,255,255,.14)';ctx.strokeRect(12,12,w-24,h-24);},false);function redraw(){sim.redraw();}const reroll=()=>{seed=Math.floor(Math.random()*1e6);$('[data-plate-number]',root).textContent=String(seed%999+1).padStart(3,'0');redraw();};['layers','pressure','grain'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',redraw));$('[data-select="fossil-palette"]',root).addEventListener('change',redraw);$('[data-action="fossil-new"]',root).addEventListener('click',reroll);$('[data-action="fossil-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'chromatic-fossil.png'));reroll();return()=>sim.stop();}

  // 09 — Organic Errors: animated cellular growth and mutation.
  function organicMarkup(){return projectFrame('Digital art / 02','Organic Errors','A living shape study. Give the structure room to grow, add pressure, and watch an orderly organism become less sure of its own outline.',`<div class="tool-canvas-wrap art-canvas-wrap"><canvas class="tool-canvas organic-canvas" aria-label="Animated abstract organic form"></canvas><div class="canvas-overlay"><span>GROWTH / <b data-growth-label>UNSTABLE</b></span><span>SPECIMEN 09-A</span></div></div><div class="tool-button-row">${action('Mutate the specimen','organic-mutate',true)}${action('Ⅱ Pause movement','organic-pause')}${action('↓ Export still','organic-export')}</div>`,panel('Growth conditions',range('Mutation','mutation',0,100,76)+range('Branching','branching',1,9,5)+range('Pulse','pulse',0,100,44)+select('Surface','organic-surface',[['membrane','Thin membrane'],['mineral','Mineral shell'],['ink','Ink growth'],['porcelain','Porcelain tissue']])+`<p class="tool-small">This is a visual organism, not a biological model. It has no known habitat.</p>`),'Built from procedural curves, recursive branches and layered cell-like forms.');}
  function bindOrganic(root){const canvas=$('.organic-canvas',root);let seed=4,paused=false,branches=[],phase=0;function mutate(){seed=Math.random()*1e5;branches=[];const n=+$('[data-range="branching"]',root).value;for(let i=0;i<n*8;i++)branches.push({a:Math.random()*Math.PI*2,r:rand(.12,.45),len:rand(.05,.22),w:rand(1,5),bend:rand(-1,1)});$('[data-growth-label]',root).textContent=pick(['UNSTABLE','OVERGROWN','REPAIRING','MISALIGNED','ALMOST READY']);sim.redraw();}
    const sim=fitCanvas(canvas,(ctx,w,h,t,dt,initial)=>{if(!paused&&!initial)phase+=dt*(+$('[data-range="pulse"]',root).value/100)*.9;ctx.fillStyle='#11131a';ctx.fillRect(0,0,w,h);const cx=w/2,cy=h/2,R=Math.min(w,h)*.28,mutation=+$('[data-range="mutation"]',root).value/100,surface=$('[data-select="organic-surface"]',root).value;const colors=surface==='mineral'?['#b8a9a2','#6d7180','#d6ff69']:surface==='ink'?['#26213a','#8b80a8','#ded3e6']:surface==='porcelain'?['#e7ddd2','#a899a0','#baa7ff']:['#a76c83','#e5a7a8','#d6ff69'];ctx.save();ctx.translate(cx,cy);ctx.rotate(Math.sin(phase*.3)*.04);ctx.beginPath();for(let i=0;i<=140;i++){const a=i/140*Math.PI*2;const noise=Math.sin(a*3+seed)*.12+Math.sin(a*7+seed*.02)*.08+Math.sin(a*13+seed*.01)*mutation*.17;const r=R*(1+noise+Math.sin(phase+a*3)*.025);const x=Math.cos(a)*r,y=Math.sin(a)*r*1.15;if(!i)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.closePath();const g=ctx.createRadialGradient(-R*.3,-R*.4,5,0,0,R*1.5);g.addColorStop(0,colors[2]);g.addColorStop(.5,colors[0]);g.addColorStop(1,'#15151c');ctx.fillStyle=g;ctx.fill();ctx.strokeStyle=colors[1];ctx.lineWidth=3;ctx.stroke();branches.forEach((b,i)=>{const a=b.a+phase*.06,r=R*b.r,x=Math.cos(a)*r,y=Math.sin(a)*r*1.15;ctx.beginPath();ctx.moveTo(x,y);ctx.bezierCurveTo(x+Math.cos(a+b.bend)*R*b.len,y+Math.sin(a+b.bend)*R*b.len,x+Math.cos(a+b.bend*2)*R*b.len*1.4,y+Math.sin(a+b.bend*2)*R*b.len*1.4,x+Math.cos(a+b.bend*2)*R*b.len*1.7,y+Math.sin(a+b.bend*2)*R*b.len*1.7);ctx.strokeStyle=colors[i%2];ctx.globalAlpha=.28+.5*mutation;ctx.lineWidth=b.w;ctx.stroke();ctx.globalAlpha=1;});for(let i=0;i<16;i++){const a=i*2.399+seed,r=R*randDummy(i);const x=Math.cos(a)*r,y=Math.sin(a)*r;ctx.fillStyle=colors[(i+1)%3];ctx.globalAlpha=.65;ctx.beginPath();ctx.ellipse(x,y,3+mutation*7,2+mutation*5,a,0,Math.PI*2);ctx.fill();}ctx.restore();},true);
    function randDummy(i){return .14+((i*37.7+seed)%67)/100;}
    $('[data-action="organic-mutate"]',root).addEventListener('click',mutate);$('[data-action="organic-pause"]',root).addEventListener('click',e=>{paused=!paused;e.currentTarget.textContent=paused?'▶ Resume movement':'Ⅱ Pause movement';});$('[data-action="organic-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'organic-error.png'));['mutation','branching','pulse'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',()=>{}));$('[data-select="organic-surface"]',root).addEventListener('change',()=>sim.redraw());mutate();return()=>sim.stop();}

  // 10 — Afterimage Studio: local image echo and color treatment.
  function afterimageMarkup(){return projectFrame('Digital art / 03','Afterimage Studio','Bring an image from your own device and give it a visual memory: offset echoes, color separation and a little persistence. The file stays in this tab.',`<div class="tool-canvas-wrap"><canvas class="tool-canvas afterimage-canvas" aria-label="Image afterimage preview"></canvas><div class="canvas-overlay"><span>LOCAL IMAGE PROCESSING</span><span data-image-state>BUILT-IN STUDY</span></div></div><div class="tool-button-row"><label class="tool-button file-button">Choose image<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" data-image-file hidden></label>${action('Reset treatment','afterimage-reset')}${action('↓ Export result','afterimage-export',true)}</div>`,panel('Visual echo',range('Echo count','echo-count',1,8,4)+range('Offset','offset',0,100,34)+range('Color separation','separation',0,100,42)+range('Grain','image-grain',0,100,18)+select('Treatment','image-mode',[['memory','Soft memory'],['misregister','Misregistered print'],['cold','Cold duplicate'],['heat','Warm residue']])+`<p class="tool-small">Images are processed locally in your browser. Nothing is sent to a server. Large photos may take a moment to draw.</p>`),'The image is never uploaded. Preview and export are handled using the browser Canvas API.');}
  function bindAfterimage(root){const canvas=$('.afterimage-canvas',root),ctx=canvas.getContext('2d');let image=null,objectUrl=null;function draw(){const w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(2,devicePixelRatio||1);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#10131a';ctx.fillRect(0,0,w,h);const mode=$('[data-select="image-mode"]',root).value,count=+$('[data-range="echo-count"]',root).value,off=+$('[data-range="offset"]',root).value/100,sep=+$('[data-range="separation"]',root).value/100,grain=+$('[data-range="image-grain"]',root).value/100;const img=image;if(img){const scale=Math.min((w*.84)/img.width,(h*.84)/img.height),iw=img.width*scale,ih=img.height*scale,x=(w-iw)/2,y=(h-ih)/2;ctx.save();for(let i=count;i>=1;i--){ctx.globalAlpha=.12+(1-i/(count+1))*.15;const dx=(i-count/2)*off*16;ctx.filter=mode==='cold'?'hue-rotate(185deg) saturate(.75)':mode==='heat'?'sepia(.6) saturate(1.7)':mode==='misregister'?'contrast(1.35) saturate(1.4)':'saturate(.85)';ctx.drawImage(img,x+dx,y+Math.abs(dx)*.25,iw,ih);}ctx.globalAlpha=1;ctx.filter='none';ctx.drawImage(img,x,y,iw,ih);if(sep>.01){ctx.globalCompositeOperation='screen';ctx.globalAlpha=sep*.28;ctx.filter='hue-rotate(130deg)';ctx.drawImage(img,x-off*18,y,iw,ih);ctx.filter='hue-rotate(-120deg)';ctx.drawImage(img,x+off*18,y,iw,ih);ctx.globalCompositeOperation='source-over';}ctx.restore();}else{ctx.fillStyle='#24202b';ctx.fillRect(w*.2,h*.13,w*.6,h*.74);ctx.fillStyle='#d6ff69';ctx.font='900 64px system-ui';ctx.textAlign='center';ctx.fillText('AFTER',w/2,h*.48);ctx.fillStyle='#baa7ff';ctx.fillText('IMAGE',w/2+12,h*.63);ctx.strokeStyle='#ff9cba';ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(w/2,h*.52,w*.17,h*.25,-.2,0,Math.PI*2);ctx.stroke();}if(grain){for(let i=0;i<Math.floor(w*h*grain*.008);i++){ctx.fillStyle=Math.random()>.5?'#fff':'#000';ctx.globalAlpha=Math.random()*.25;ctx.fillRect(Math.random()*w,Math.random()*h,1.2,1.2);}ctx.globalAlpha=1;}}
    function redraw(){draw();}const ro=new ResizeObserver(redraw);ro.observe(canvas);function setImage(img){image=img;$('[data-image-state]',root).textContent=img?'LOCAL IMAGE LOADED':'BUILT-IN STUDY';draw();}
    $('[data-image-file]',root).addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(!/^image\/(png|jpeg|webp|gif)$/.test(f.type)){toast(null,'Please choose a PNG, JPEG, WebP or GIF image.');return;}if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(f);const img=new Image();img.onload=()=>setImage(img);img.onerror=()=>toast(null,'That image could not be opened.');img.src=objectUrl;});['echo-count','offset','separation','image-grain'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',redraw));$('[data-select="image-mode"]',root).addEventListener('change',redraw);$('[data-action="afterimage-reset"]',root).addEventListener('click',()=>{$('[data-image-file]',root).value='';setImage(null);});$('[data-action="afterimage-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'afterimage-study.png'));draw();return()=>{ro.disconnect();if(objectUrl)URL.revokeObjectURL(objectUrl);};}

  // 11 — Pocket Universe: an arcade-sized orbit courier.
  function pocketMarkup(){return projectFrame('Tiny game / 01','Pocket Universe','Deliver a little packet of starlight through a crowded pocket of space. Collect the bright fragments. Do not let the dark objects touch you.',`<div class="tool-canvas-wrap game-wrap"><canvas class="tool-canvas pocket-canvas" aria-label="Pocket Universe game"></canvas><div class="game-hud"><span>SHARDS <b data-score>0 / 7</b></span><span>HULL <b data-hull>100%</b></span><span>TIME <b data-time>00:00</b></span></div><div class="game-start show" data-game-cover><div><strong>THE DELIVERY IS LATE.</strong><span>Move with WASD / arrow keys, or drag on the field.</span><button class="tool-button primary" type="button" data-action="pocket-start">Begin delivery</button></div></div></div><div class="tool-button-row">${action('↻ Restart run','pocket-restart')}</div>`,panel('Flight notes',`<p class="tool-small">Collect all seven light shards and reach the small gate. The dark masses pull your craft off course. Your ship follows your input gently, so lead your turns.</p><div class="tool-readout"><span>Delivery record</span><strong data-delivery>NOT STARTED</strong></div><div class="tool-readout"><span>Fastest completed run</span><strong data-best-delivery>—</strong></div><p class="tool-small">Keyboard and touch controls are both supported. Click the field and use your arrow keys or WASD.</p>`),'A short arcade game. No account, score upload or external assets.');}
  function bindPocket(root){const canvas=$('.pocket-canvas',root),cover=$('[data-game-cover]',root),recordKey='curioid-pocket-universe-best-v1';let bestTime=Infinity;try{const stored=Number(localStorage.getItem(recordKey));if(stored>0)bestTime=stored;}catch(_){}function showBest(){ $('[data-best-delivery]',root).textContent=Number.isFinite(bestTime)?`${String(Math.floor(bestTime/60)).padStart(2,'0')}:${String(Math.floor(bestTime%60)).padStart(2,'0')}`:'—';}let w=1,h=1,ctx,raf=0,running=false,last=0,startAt=0,score=0,hull=100,player={x:0,y:0,vx:0,vy:0},target={x:.5,y:.5},keys={},shards=[],hazards=[],gate={x:.85,y:.5},time=0;function reset(){score=0;hull=100;time=0;player={x:.12,y:.5,vx:0,vy:0};target={x:.12,y:.5};shards=Array.from({length:7},()=>({x:rand(.18,.83),y:rand(.1,.9),got:false,p:rand(0,7)}));hazards=Array.from({length:5},()=>({x:rand(.25,.83),y:rand(.1,.9),r:rand(.025,.05),p:rand(0,7),m:rand(.15,.4)}));gate={x:.9,y:.5};updateHud();draw();}
    function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(2,devicePixelRatio||1);w=r.width;h=r.height;canvas.width=w*d;canvas.height=h*d;ctx=canvas.getContext('2d');ctx.setTransform(d,0,0,d,0,0);draw();}const ro=new ResizeObserver(resize);ro.observe(canvas);
    function updateHud(){$('[data-score]',root).textContent=`${score} / 7`;$('[data-hull]',root).textContent=`${Math.max(0,Math.round(hull))}%`;$('[data-time]',root).textContent=`${String(Math.floor(time/60)).padStart(2,'0')}:${String(Math.floor(time%60)).padStart(2,'0')}`;}
    function draw(t=0){if(!ctx)return;ctx.fillStyle='#0d1420';ctx.fillRect(0,0,w,h);for(let i=0;i<80;i++){const x=(i*97%997)/997*w,y=(i*173%991)/991*h;ctx.fillStyle='rgba(220,232,255,.35)';ctx.fillRect(x,y,1.2,1.2);}ctx.strokeStyle='rgba(186,167,255,.13)';ctx.lineWidth=1;for(let r=40;r<Math.max(w,h);r+=45){ctx.beginPath();ctx.ellipse(w*.48,h*.5,r,r*.56,0,0,Math.PI*2);ctx.stroke();}
      shards.forEach(s=>{if(s.got)return;const x=s.x*w,y=s.y*h,a=(t*.001+s.p);ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle='#d6ff69';ctx.shadowColor='#d6ff69';ctx.shadowBlur=14;ctx.beginPath();ctx.moveTo(0,-8);ctx.lineTo(6,0);ctx.lineTo(0,8);ctx.lineTo(-6,0);ctx.closePath();ctx.fill();ctx.restore();});hazards.forEach(z=>{const x=z.x*w+Math.sin(t*.0004+z.p)*13,y=z.y*h+Math.cos(t*.0005+z.p)*9;const g=ctx.createRadialGradient(x,y,2,x,y,z.r*w*2);g.addColorStop(0,'#17151e');g.addColorStop(.55,'#111018');g.addColorStop(1,'rgba(126,92,150,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,z.r*w*2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#887095';ctx.beginPath();ctx.arc(x,y,z.r*w,0,Math.PI*2);ctx.stroke();});const gx=gate.x*w,gy=gate.y*h;ctx.strokeStyle=score===7?'#d6ff69':'#baa7ff';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(gx,gy,17,35,0,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.ellipse(gx,gy,7,22,0,0,Math.PI*2);ctx.stroke();const px=player.x*w,py=player.y*h;ctx.save();ctx.translate(px,py);ctx.rotate(Math.atan2(player.vy,player.vx));ctx.fillStyle='#d6ff69';ctx.beginPath();ctx.moveTo(13,0);ctx.lineTo(-9,-7);ctx.lineTo(-5,0);ctx.lineTo(-9,7);ctx.closePath();ctx.fill();ctx.restore();}
    function frame(now){if(!running)return;const dt=Math.min(.04,(now-last)/1000||.016);last=now;time+=dt;let ax=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0),ay=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0);const dx=target.x-player.x,dy=target.y-player.y;if(Math.abs(dx)+Math.abs(dy)>.008){ax+=clamp(dx*5,-1,1);ay+=clamp(dy*5,-1,1);}player.vx=(player.vx+ax*dt*.75)*.985;player.vy=(player.vy+ay*dt*.75)*.985;hazards.forEach(z=>{const hx=z.x+Math.sin(now*.0004+z.p)*.013,hy=z.y+Math.cos(now*.0005+z.p)*.013,dx=hx-player.x,dy=hy-player.y,d=Math.hypot(dx,dy)+.01,force=z.m*.0008/(d*d);player.vx-=dx*force;player.vy-=dy*force;});player.x=clamp(player.x+player.vx*dt,.025,.975);player.y=clamp(player.y+player.vy*dt,.035,.965);shards.forEach(s=>{if(!s.got&&Math.hypot((s.x-player.x)*w,(s.y-player.y)*h)<15){s.got=true;score++;}});hazards.forEach(z=>{const hx=z.x+Math.sin(now*.0004+z.p)*.013,hy=z.y+Math.cos(now*.0005+z.p)*.013;if(Math.hypot((hx-player.x)*w,(hy-player.y)*h)<z.r*w+8)hull-=dt*19;});if(hull<=0|| (score===7&&Math.hypot((gate.x-player.x)*w,(gate.y-player.y)*h)<28)){running=false;cover.classList.add('show');cover.querySelector('strong').textContent=hull<=0?'DELIVERY INTERRUPTED.':'DELIVERY ACCEPTED.';cover.querySelector('span').textContent=hull<=0?'The hull gave up before the cargo did.':'Seven shards delivered. The recipient signed for them twice.';cover.querySelector('button').textContent='Run it again';$('[data-delivery]',root).textContent=hull<=0?'INCOMPLETE':'DELIVERED';if(hull>0&&time<bestTime){bestTime=time;try{localStorage.setItem(recordKey,String(bestTime));}catch(_){}showBest();}}updateHud();draw(now);raf=requestAnimationFrame(frame);}
    function start(){reset();cover.classList.remove('show');running=true;last=performance.now();$('[data-delivery]',root).textContent='IN TRANSIT';cancelAnimationFrame(raf);raf=requestAnimationFrame(frame);}function setTarget(e){const r=canvas.getBoundingClientRect();target={x:clamp((e.clientX-r.left)/r.width,0,1),y:clamp((e.clientY-r.top)/r.height,0,1)};}
    canvas.addEventListener('pointerdown',e=>{setTarget(e);canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(e.buttons||e.pointerType==='touch')setTarget(e);});const keydown=e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key)&&running)e.preventDefault();keys[e.key]=true;};const keyup=e=>keys[e.key]=false;document.addEventListener('keydown',keydown);document.addEventListener('keyup',keyup);$('[data-action="pocket-start"]',root).addEventListener('click',start);$('[data-action="pocket-restart"]',root).addEventListener('click',start);reset();showBest();return()=>{running=false;cancelAnimationFrame(raf);ro.disconnect();document.removeEventListener('keydown',keydown);document.removeEventListener('keyup',keyup);};}

  // 12 — One Button Ritual: timing and nerve.
  function ritualMarkup(){return projectFrame('Tiny game / 02','One-Button Ritual','A machine asks for a single well-timed answer. Keep the pulse inside the mark. It will slowly stop being polite.',`<div class="ritual-stage"><div class="ritual-ring"><div class="ritual-target"></div><div class="ritual-pointer" data-ritual-pointer></div><div class="ritual-core"><strong data-ritual-round>01</strong><small>ROUND</small></div></div><div class="ritual-feedback" data-ritual-feedback>WAIT FOR THE MARK</div><button class="tool-button primary ritual-hit" type="button" data-action="ritual-hit">PRESS / SPACE</button></div>`,panel('Ritual record',`<div class="tool-readout"><span>Successful marks</span><strong data-ritual-score>0</strong></div><div class="tool-readout"><span>Best chain</span><strong data-ritual-chain>0</strong></div><div class="tool-readout"><span>Precision</span><strong data-ritual-precision>—</strong></div><p class="tool-small">Press the button or Space when the moving pointer crosses the bright segment. Complete twelve rounds. Misses do not end the ritual, but they do remember.</p>${action('Restart ritual','ritual-reset')}`),'No reflex score is sent anywhere. The game uses the local frame clock.');}
  function bindRitual(root){let savedBest=0;try{savedBest=Number(localStorage.getItem('curioid-ritual-best-chain-v1'))||0;}catch(_){}let angle=0,raf=0,running=true,round=1,score=0,chain=0,best=savedBest,precision=[],target=rand(-Math.PI,Math.PI),width=.65,last=0,done=false;const pointer=$('[data-ritual-pointer]',root),stage=$('.ritual-ring',root);function setTarget(){target=rand(-Math.PI,Math.PI);width=Math.max(.13,.65-round*.04);const el=$('.ritual-target',root);el.style.transform=`rotate(${target}rad)`;el.style.setProperty('--zone',`${width}rad`);el.style.background=`conic-gradient(from ${target-width/2}rad, transparent 0deg, transparent ${((Math.PI*2-width)/(Math.PI*2))*360}deg, rgba(214,255,105,.8) ${((Math.PI*2-width)/(Math.PI*2))*360}deg, rgba(214,255,105,.8) 360deg)`;}
    function update(){ $('[data-ritual-round]',root).textContent=String(round).padStart(2,'0');$('[data-ritual-score]',root).textContent=score;$('[data-ritual-chain]',root).textContent=best;$('[data-ritual-precision]',root).textContent=precision.length?`${Math.round(precision.reduce((a,b)=>a+b,0)/precision.length)}%`:'—';}
    function frame(now){if(!running)return;const dt=Math.min(.04,(now-last)/1000||.016);last=now;angle=(angle+dt*(1.5+round*.12))%(Math.PI*2);pointer.style.transform=`rotate(${angle}rad)`;raf=requestAnimationFrame(frame);}function hit(){if(done)return;let diff=Math.atan2(Math.sin(angle-target),Math.cos(angle-target)),accuracy=clamp(1-Math.abs(diff)/(width/2),0,1);if(accuracy>0){score++;chain++;if(chain>best){best=chain;savedBest=best;try{localStorage.setItem('curioid-ritual-best-chain-v1',String(best));}catch(_){}}precision.push(Math.round(accuracy*100));$('[data-ritual-feedback]',root).textContent=accuracy>.82?'CLEAN. TOO CLEAN.':accuracy>.45?'ACCEPTED.':'BARELY ACCEPTED.';}else{chain=0;$('[data-ritual-feedback]',root).textContent='THE MARK MOVED. OR YOU DID.';}round++;if(round>12){done=true;running=false;cancelAnimationFrame(raf);$('[data-ritual-feedback]',root).textContent=`RITUAL COMPLETE · ${score} / 12`;}$('[data-ritual-round]',root).textContent=String(Math.min(round,12)).padStart(2,'0');update();setTarget();}
    function reset(){round=1;score=0;chain=0;best=savedBest;precision=[];done=false;running=true;angle=0;last=performance.now();$('[data-ritual-feedback]',root).textContent='WAIT FOR THE MARK';setTarget();update();cancelAnimationFrame(raf);raf=requestAnimationFrame(frame);}
    $('[data-action="ritual-hit"]',root).addEventListener('click',hit);$('[data-action="ritual-reset"]',root).addEventListener('click',reset);const key=e=>{if(e.code==='Space'&&running){e.preventDefault();hit();}};document.addEventListener('keydown',key);reset();return()=>{running=false;cancelAnimationFrame(raf);document.removeEventListener('keydown',key);};}

  // 13 — The Last Corridor: a short branching exploration with a persistent watcher.
  function corridorMarkup(){return projectFrame('Tiny game / 03','The Last Corridor','There are three doors at the end of every hallway. The building says you have been here before. It is not clear whether that is a warning or an instruction.',`<div class="corridor-view" data-corridor-view><div class="corridor-ceiling"></div><div class="corridor-walls"></div><div class="corridor-floor"></div><div class="corridor-door"></div><div class="corridor-light"></div><span class="corridor-sign" data-corridor-sign>LEVEL 01</span><span class="corridor-shadow" data-corridor-shadow></span></div><div class="corridor-narrative" data-corridor-text>The corridor smells of rain. There is no rain in the building.</div><div class="corridor-choices" data-corridor-choices></div>`,panel('Building record',`<div class="tool-readout"><span>Hallway</span><strong data-corridor-room>01 / 09</strong></div><div class="tool-readout"><span>Repeated turns</span><strong data-corridor-repeat>0</strong></div><div class="tool-readout"><span>Found object</span><strong data-corridor-object>NONE</strong></div><p class="tool-small">Reach the end of the corridor. The watcher does not follow the same rules as the doors. Your place is saved in this browser until you choose Start over.</p>${action('Start over','corridor-reset')}`),'A short narrative maze. Choices alter the route, clues and final room.');}
  function bindCorridor(root){const storageKey='curioid-last-corridor-progress-v1';let room=1,repeats=0,lastChoice='',object='NONE',watcher=0;try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&Number.isFinite(saved.room)){room=clamp(Math.floor(saved.room),1,10);repeats=Math.max(0,Number(saved.repeats)||0);lastChoice=typeof saved.lastChoice==='string'?saved.lastChoice:'';object=typeof saved.object==='string'?saved.object:'NONE';watcher=clamp(Number(saved.watcher)||0,0,4);}}catch(_){}const saveProgress=()=>{try{localStorage.setItem(storageKey,JSON.stringify({room,repeats,lastChoice,object,watcher}));}catch(_){}};const endings=['The door opens onto the same corridor, but the lights are now behind you.','The exit is a street at noon. The street has no buildings on either side.','The final room contains a coat that is still warm. Its pockets are empty except for your key.'];const texts=[['A narrow hall. Something small is rolling at the far end.','The left door has a brass handle. It is colder than the wall.','A light flickers behind the right door. The rhythm resembles a name.'],['The carpet has one damp footprint, pointing toward the ceiling.','A service hatch is ajar. There is a soft ticking inside.','The walls are warm here, like the building has a fever.'],['A framed evacuation map shows this hallway from above. There are four extra rooms.','A telephone rings once, then stops when you approach.','A window looks out onto another corridor. Someone is standing with their back to you.']];function render(){const idx=(room-1)%3;$('[data-corridor-room]',root).textContent=`${String(room).padStart(2,'0')} / 09`;$('[data-corridor-repeat]',root).textContent=repeats;$('[data-corridor-object]',root).textContent=object;$('[data-corridor-sign]',root).textContent=`LEVEL ${String(room).padStart(2,'0')}`;$('[data-corridor-text]',root).textContent=room>9?pick(endings):pick(texts[idx]);$('[data-corridor-shadow]',root).style.opacity=String(clamp(watcher*.22,0,.92));const choices=['LEFT','STRAIGHT','RIGHT'];$('[data-corridor-choices]',root).innerHTML=room>9?`<button class="tool-button primary" data-corridor-end>Leave the building</button>`:choices.map((c,i)=>`<button type="button" class="tool-button" data-choice="${c.toLowerCase()}">${c}<small>${['A door with a small number','A door without a handle','A door that is slightly open'][i]}</small></button>`).join('');$$('[data-choice]',root).forEach(b=>b.addEventListener('click',()=>choose(b.dataset.choice)));$('[data-corridor-end]',root)?.addEventListener('click',reset);}
    function choose(c){if(c===lastChoice)repeats++;else repeats=Math.max(0,repeats-1);lastChoice=c;watcher=clamp(watcher+(repeats>1?1:Math.random()>.65?1:0),0,4);room++;if(room===4&&object==='NONE')object='BRASS KEY';if(room===7&&watcher>1)object='WARM COAT';saveProgress();render();}function reset(){room=1;repeats=0;lastChoice='';object='NONE';watcher=0;$('[data-corridor-view]',root).classList.remove('corridor-end');saveProgress();render();}$('[data-action="corridor-reset"]',root).addEventListener('click',reset);render();return()=>{};}

  // 14 — Frequency Garden: interactive sound plants whose coordinates set pitch and tone.
  function frequencyMarkup(){return projectFrame('Sound & motion / 01','Frequency Garden','Plant a few tones, then move around them. The garden is an instrument: each bloom has a pitch, a place and a tendency to return.',`<div class="tool-canvas-wrap frequency-wrap"><canvas class="tool-canvas frequency-canvas" aria-label="Interactive sound garden"></canvas><div class="canvas-overlay"><span>TOUCH THE BLOOMS TO PLAY</span><span data-plant-count>0 PLANTS</span></div></div><div class="tool-button-row">${action('＋ Plant a tone','plant-tone',true)}${action('Clear garden','clear-garden')}${action('↓ Export garden','garden-export')}</div>`,panel('Sound environment',range('Resonance','resonance',0,100,55)+range('Volume','garden-volume',0,100,35)+select('Waveform','garden-wave',[['sine','Sine / soft'],['triangle','Triangle / warm'],['sawtooth','Saw / bright'],['square','Square / hollow']])+`<p class="tool-small">Audio is silent until you touch a bloom or plant a tone. Click the garden to place a plant at that point.</p>`),'Uses generated tones through Web Audio. Browsers require a user gesture before audio starts.');}
  function bindFrequency(root){const canvas=$('.frequency-canvas',root);const storageKey='curioid-frequency-garden-v1';let plants=[],ac=null,master=null,raf=0;try{const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(saved))plants=saved.filter(p=>p&&Number.isFinite(p.x)&&Number.isFinite(p.y)).slice(0,20);}catch(_){}function draw(ctx,w,h,t){ctx.fillStyle='#101a1a';ctx.fillRect(0,0,w,h);for(let i=0;i<8;i++){ctx.strokeStyle='rgba(133,230,218,.08)';ctx.beginPath();ctx.ellipse(w/2,h/2,35+i*34,18+i*20,0,0,Math.PI*2);ctx.stroke();}plants.forEach(p=>{const x=p.x*w,y=p.y*h,pulse=1+Math.sin(t*2+p.phase)*.12;const g=ctx.createRadialGradient(x,y,2,x,y,20*pulse);g.addColorStop(0,p.color);g.addColorStop(1,p.color+'00');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,22*pulse,0,Math.PI*2);ctx.fill();ctx.strokeStyle=p.color;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x-12,y-30,x,y-45*pulse);ctx.stroke();ctx.fillStyle=p.color;ctx.beginPath();ctx.ellipse(x,y-47*pulse,10,5,Math.sin(t+p.phase),0,Math.PI*2);ctx.fill();});}
    const sim=fitCanvas(canvas,draw,true);function ensure(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return null;if(!ac){ac=new AC();master=ac.createGain();master.gain.value=+$('[data-range="garden-volume"]',root).value/100*.3;master.connect(ac.destination);}if(ac.state==='suspended')ac.resume();return ac;}
    function tone(p){const c=ensure();if(!c)return;master.gain.setTargetAtTime(+$('[data-range="garden-volume"]',root).value/100*.3,c.currentTime,.05);const o=c.createOscillator(),g=c.createGain(),f=c.createBiquadFilter();o.type=$('[data-select="garden-wave"]',root).value;o.frequency.value=110+Math.pow(2,p.x*4)*55+p.y*500;f.type='lowpass';f.frequency.value=500+Number($('[data-range="resonance"]',root).value)*55;g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(.22,c.currentTime+.025);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.65);o.connect(f);f.connect(g);g.connect(master);o.start();o.stop(c.currentTime+.7);}
    function plant(x,y){if(plants.length>=20){toast(null,'The garden is full. Clear a few plants to make room.');return;}const p={x,y,color:pick(['#d6ff69','#85e6da','#baa7ff','#ff9cba']),phase:rand(0,6)};plants.push(p);try{localStorage.setItem(storageKey,JSON.stringify(plants));}catch(_){}$('[data-plant-count]',root).textContent=`${plants.length} PLANTS`;tone(p);sim.redraw();}
    canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect();plant(clamp((e.clientX-r.left)/r.width,.05,.95),clamp((e.clientY-r.top)/r.height,.12,.85));});$('[data-action="plant-tone"]',root).addEventListener('click',()=>plant(rand(.12,.88),rand(.2,.8)));$('[data-action="clear-garden"]',root).addEventListener('click',()=>{plants=[];try{localStorage.removeItem(storageKey);}catch(_){}$('[data-plant-count]',root).textContent='0 PLANTS';sim.redraw();});$('[data-action="garden-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'frequency-garden.png'));$('[data-range="garden-volume"]',root).addEventListener('input',()=>{if(master)master.gain.value=+$('[data-range="garden-volume"]',root).value/100*.3;});$('[data-plant-count]',root).textContent=`${plants.length} PLANTS`;return()=>{sim.stop();if(ac)ac.close().catch(()=>{});};}

  // 15 — Motion Residue: pointer-driven trails and drawing.
  function motionMarkup(){return projectFrame('Sound & motion / 02','Motion Residue','Move through the frame. Your gesture leaves a trace that slowly becomes its own object. It works with a mouse, finger or pen.',`<div class="tool-canvas-wrap motion-wrap"><canvas class="tool-canvas motion-canvas" aria-label="Draw with pointer movement"></canvas><div class="canvas-overlay"><span>MOVE / DRAW / RETURN</span><span data-motion-strokes>0 TRACES</span></div></div><div class="tool-button-row">${action('Clear the surface','motion-clear')}${action('New color','motion-color')}${action('↓ Export drawing','motion-export',true)}</div>`,panel('Trace properties',select('Trace type','trace-type',[['ribbon','Ribbon trail'],['echo','Echo copies'],['particle','Particle wake'],['line','Single line']])+range('Persistence','persistence',1,100,68)+range('Symmetry','motion-symmetry',1,12,1)+range('Brush size','brush-size',1,30,8)+`<p class="tool-small">Draw inside the frame. On touchscreens, the drawing surface captures your finger while it is down.</p>`),'Pointer Events are used so mouse, touch and pen input share the same drawing behavior.');}
  function bindMotion(root){const canvas=$('.motion-canvas',root);let points=[],drawing=false,color='#d6ff69',count=0;function paint(ctx,w,h,t,dt,initial){if(initial){ctx.fillStyle='#10131a';ctx.fillRect(0,0,w,h);return;}ctx.fillStyle='rgba(16,19,26,.16)';ctx.fillRect(0,0,w,h);const mode=$('[data-select="trace-type"]',root).value,sym=+$('[data-range="motion-symmetry"]',root).value,size=+$('[data-range="brush-size"]',root).value;points=points.filter(p=>p.life>0);points.forEach(p=>p.life-=dt*.2);points.forEach((p,i)=>{const alpha=clamp(p.life,0,1),px=p.x*w,py=p.y*h;for(let s=0;s<sym;s++){const a=s*Math.PI*2/sym;const x=w/2+(px-w/2)*Math.cos(a)-(py-h/2)*Math.sin(a),y=h/2+(px-w/2)*Math.sin(a)+(py-h/2)*Math.cos(a);ctx.globalAlpha=alpha*.8;ctx.strokeStyle=p.color;ctx.fillStyle=p.color;ctx.lineWidth=size*(.25+p.life);if(mode==='particle'){for(let j=0;j<4;j++){ctx.beginPath();ctx.arc(x+Math.sin(p.life*9+j)*8,y+Math.cos(p.life*8+j)*8,1.5+p.life*2,0,Math.PI*2);ctx.fill();}}else{ctx.beginPath();ctx.arc(x,y,mode==='echo'?size*(.5+p.life):size*.45,0,Math.PI*2);ctx.stroke();if(mode==='ribbon'){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-p.dx*w*.07,y-p.dy*h*.07);ctx.stroke();}}}});ctx.globalAlpha=1;}
    const sim=fitCanvas(canvas,paint,true);function add(e){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;if(points.length>300)points.splice(0,60);points.push({x,y,dx:0,dy:0,life:1,color});}canvas.addEventListener('pointerdown',e=>{drawing=true;canvas.setPointerCapture(e.pointerId);add(e);});canvas.addEventListener('pointermove',e=>{if(!drawing)return;const prev=points[points.length-1];add(e);const p=points[points.length-1];p.dx=p.x-prev.x;p.dy=p.y-prev.y;count++;$('[data-motion-strokes]',root).textContent=`${count} TRACES`;});const end=()=>drawing=false;canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);$('[data-action="motion-clear"]',root).addEventListener('click',()=>{points=[];count=0;$('[data-motion-strokes]',root).textContent='0 TRACES';sim.redraw();});$('[data-action="motion-color"]',root).addEventListener('click',()=>{color=pick(['#d6ff69','#baa7ff','#ff9cba','#85e6da','#f5d8a5']);toast(null,'New trace color selected.');});$('[data-action="motion-export"]',root).addEventListener('click',()=>saveCanvas(canvas,'motion-residue.png'));return()=>sim.stop();}

  // 16 — Noise Choir: an atmospheric multi-voice synthesizer.
  function choirMarkup(){return projectFrame('Sound & motion / 03','Noise Choir','A choir made from simple waveforms. Add voices, change their intervals and make a chord that almost resolves.',`<div class="choir-stage"><div class="choir-orbits" data-choir-orbits><span></span><span></span><span></span><span></span><span></span></div><div class="choir-center"><strong data-choir-state>SILENT</strong><small>FIVE VOICES</small></div></div><div class="voice-list">${['I','II','III','IV','V'].map((v,i)=>`<button type="button" class="voice-chip${i<3?' on':''}" data-voice="${i}" aria-pressed="${i<3}"><span>${v}</span><small>${['ROOT','FIFTH','MINOR','SEVENTH','SHADOW'][i]}</small></button>`).join('')}</div><div class="tool-button-row">${action('▶ Open the choir','choir-play',true)}${action('■ Silence','choir-stop')}${action('Random arrangement','choir-random')}</div>`,panel('Voice direction',select('Mood','choir-mood',[['low','Low room'],['bright','Thin daylight'],['uneasy','Unsettled interval'],['warm','Warm machinery']])+range('Detuning','detuning',0,100,26)+range('Room / reverb','reverb',0,100,38)+range('Master level','choir-volume',0,100,30)+`<p class="tool-small">Nothing plays until you open the choir. Use the five voices to add or remove layers. Keep the volume low when exploring the more dissonant settings.</p>`),'A browser-generated synthesizer. Audio nodes are created on interaction and closed when the window is closed.');}
  function bindChoir(root){let ac=null,master=null,voices=[],reverb=null,playing=false;const voiceKey='curioid-noise-choir-voices-v1';try{const saved=JSON.parse(localStorage.getItem(voiceKey)||'null');if(Array.isArray(saved)&&saved.length===5){$$('.voice-chip',root).forEach((b,i)=>{b.classList.toggle('on',Boolean(saved[i]));b.setAttribute('aria-pressed',String(Boolean(saved[i])));});}}catch(_){}const saveVoices=()=>{try{localStorage.setItem(voiceKey,JSON.stringify($$('.voice-chip',root).map(b=>b.classList.contains('on'))));}catch(_){}};const ratios=[1,1.5,1.1892,1.7778,2.013];function ensure(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC){toast(null,'Audio is unavailable in this browser.');return false;}if(!ac){ac=new AC();master=ac.createGain();master.gain.value=+$('[data-range="choir-volume"]',root).value/100*.32;const delay=ac.createDelay(2),feedback=ac.createGain(),wet=ac.createGain();delay.delayTime.value=.31;feedback.gain.value=.28;wet.gain.value=+$('[data-range="reverb"]',root).value/100*.35;delay.connect(feedback);feedback.connect(delay);delay.connect(wet);wet.connect(master);master.connect(ac.destination);reverb={delay,wet};}if(ac.state==='suspended')ac.resume();return true;}
    function start(){if(!ensure())return;stopVoices();const mood=$('[data-select="choir-mood"]',root).value;const base=mood==='low'?82.4:mood==='bright'?164.8:mood==='warm'?110:98;const active=$$('.voice-chip.on',root);active.forEach(b=>{const i=+b.dataset.voice,o=ac.createOscillator(),g=ac.createGain(),filter=ac.createBiquadFilter();o.type=mood==='warm'?'triangle':mood==='uneasy'?'sawtooth':'sine';o.frequency.value=base*ratios[i];o.detune.value=(i-2)*Number($('[data-range="detuning"]',root).value)*.35;filter.type='lowpass';filter.frequency.value=mood==='bright'?3000:950+i*170;g.gain.value=.0001;o.connect(filter);filter.connect(g);g.connect(master);g.connect(reverb.delay);g.gain.setTargetAtTime(.12/(1+i*.22),ac.currentTime,.35);o.start();voices.push({o,g});});playing=true;$('[data-choir-state]',root).textContent='SINGING';$('.choir-orbits',root).classList.add('active');master.gain.setTargetAtTime(+$('[data-range="choir-volume"]',root).value/100*.32,ac.currentTime,.08);}
    function stopVoices(){if(ac)voices.forEach(v=>{try{v.g.gain.setTargetAtTime(.0001,ac.currentTime,.05);v.o.stop(ac.currentTime+.3);}catch(e){}});voices=[];playing=false;$('[data-choir-state]',root).textContent='SILENT';$('.choir-orbits',root).classList.remove('active');}
    $$('.voice-chip',root).forEach(b=>b.addEventListener('click',()=>{b.classList.toggle('on');b.setAttribute('aria-pressed',String(b.classList.contains('on')));saveVoices();if(playing)start();}));$('[data-action="choir-play"]',root).addEventListener('click',start);$('[data-action="choir-stop"]',root).addEventListener('click',stopVoices);$('[data-action="choir-random"]',root).addEventListener('click',()=>{$$('.voice-chip',root).forEach(b=>{const on=Math.random()>.42;b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on));});saveVoices();if(playing)start();});saveVoices();['choir-volume','reverb','detuning'].forEach(k=>$(`[data-range="${k}"]`,root).addEventListener('input',()=>{if(master)master.gain.value=+$('[data-range="choir-volume"]',root).value/100*.32;if(reverb)reverb.wet.gain.value=+$('[data-range="reverb"]',root).value/100*.35;if(playing)start();}));$('[data-select="choir-mood"]',root).addEventListener('change',()=>{if(playing)start();});return()=>{stopVoices();if(ac)ac.close().catch(()=>{});};}

  // 17 — Museum of Almost Real Things: a browsable object cabinet.
  const artifacts=[
    ['The Third-Tine Spoon','1954 · Housewares','A serving spoon manufactured with three tines at its tip. The third tine is visible in photographs but absent from the physical object. Its shadow continues to show all three.','The spoon was recalled after customers began setting three places at tables for two.','SPOON / 054','spoon'],
    ['Weather Dial No. 13','1978 · Domestic instruments','A brass wall dial with settings for sun, rain, fog and a narrow blank space between fog and sun. The blank space is labelled “later”.','The manufacturer said the thirteenth setting was a printing error. No replacement face was ever produced.','DIAL / 178','dial'],
    ['Motel Key Zero','1986 · Hospitality','A heavy room key from a motel that listed rooms 1 through 28. The tag reads 0. The key fits the linen cupboard, the front door and a lock that is no longer in the building.','The front desk ledger shows room zero as occupied every night of the motel’s operation.','KEY / 086','key'],
    ['The Quiet Phonograph','1992 · Audio equipment','A portable record player with a felt platter and no speaker. Its instruction card describes how to adjust the volume.','A service note says “unit plays correctly; sound remains inside”.','AUDIO / 092','record'],
    ['Window Sample C','2001 · Architectural salvage','A double-glazed window removed from a building that had no exterior walls. Condensation forms on the inner pane only when someone stands behind it.','The sample is stored facing inward. Curators disagree about which side that means.','GLASS / 201','window'],
    ['The Unsent Postcard','2011 · Correspondence','A postcard showing a seaside town at low tide. The address is legible, but the message has been written on the stamp.','The post office returned it to the sender, citing an incomplete destination. The sender field is blank.','MAIL / 211','postcard'],
    ['A Map of the Back Room','2019 · Cartography','A folded map of the museum’s storage room. Each time it is opened, one additional shelf appears. The printed legend has no symbol for shelves.','The map is kept in a drawer that is not shown on the map.','MAP / 219','map'],
    ['The Familiar Button','2023 · Interface parts','A single beige keyboard key marked “HOME”. It has no stem, no switch and no matching keyboard. Pressing it leaves a faint impression in the pad beneath it.','It was found in the pocket of a coat that had been on display for six years.','KEY / 223','button']
  ];
  function museumMarkup(){return projectFrame('Strange archive / 01','Museum of Almost Real Things','Eight catalogued objects from ordinary collections. Their records are complete. Their explanations are not.',`<div class="museum-grid" data-museum-grid></div><div class="museum-detail" data-museum-detail><div class="museum-detail-art" data-museum-art></div><div><p class="tool-eyebrow" data-museum-code>OBJECT / 054</p><h4 data-museum-title>The Third-Tine Spoon</h4><p data-museum-copy>Select an object to inspect its record.</p><blockquote data-museum-note></blockquote><div class="tool-button-row"><button type="button" class="tool-button" data-museum-favorite>☆ Save artifact</button></div></div></div><div class="saved-ideas" data-museum-saved aria-live="polite"></div>`,panel('Collection index',`<div class="tool-readout"><span>Items catalogued</span><strong>08</strong></div><p class="tool-small">Select an object. Every specimen has a standard acquisition record and a note from the collection staff.</p>${action('Select another object','museum-random')}`),'A fictional collection. No real institution, place or historical object is being represented.');}
  function bindMuseum(root){const grid=$('[data-museum-grid]',root),storageKey='curioid-museum-favorites-v1';let favorites=[];try{const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(saved))favorites=saved.filter(n=>Number.isInteger(n)&&n>=0&&n<artifacts.length);}catch(_){}let selectedIndex=0;function art(type){const artMap={spoon:'<ellipse cx="100" cy="50" rx="25" ry="34"/><path d="M100 80v85m-12-4 24 0"/>',dial:'<circle cx="100" cy="90" r="62"/><path d="M100 32v14m0 88v14M42 90h14m88 0h14M100 90l32-33"/><text x="100" y="104" text-anchor="middle">13</text>',key:'<path d="M36 75a34 34 0 1 1 68 0a34 34 0 0 1-68 0m68 0h72v18h-21v18h-18V93h-33"/>',record:'<circle cx="100" cy="90" r="60"/><circle cx="100" cy="90" r="36"/><circle cx="100" cy="90" r="8"/><path d="M100 30v120"/>',window:'<rect x="42" y="32" width="116" height="116"/><path d="M100 32v116M42 90h116"/><path d="M52 42l96 96M148 42 52 138"/>',postcard:'<rect x="32" y="45" width="136" height="90" rx="4"/><path d="m40 112 38-37 28 19 24-24 30 42"/><rect x="141" y="50" width="18" height="21"/>',map:'<path d="M36 43l48-12 38 14 42-13v112l-42 13-38-14-48 12zM84 31v112m38-98v112"/>',button:'<rect x="48" y="45" width="104" height="92" rx="16"/><rect x="64" y="59" width="72" height="64" rx="9"/><text x="100" y="99" text-anchor="middle">HOME</text>'};return `<svg viewBox="0 0 200 180" aria-hidden="true"><g fill="none" stroke="#d6ff69" stroke-width="5" stroke-linecap="round" stroke-linejoin="round">${artMap[type]}</g></svg>`;}
    function renderFavorites(){const box=$('[data-museum-saved]',root);box.innerHTML=favorites.length?'<strong>Saved artifacts</strong>'+favorites.map(i=>`<button type="button" data-museum-open="${i}">${esc(artifacts[i][0])}</button>`).join(''):'<span>No artifacts saved yet. Use “Save artifact” on an object you want to keep.</span>';$$('[data-museum-open]',box).forEach(b=>b.addEventListener('click',()=>show(+b.dataset.museumOpen)));}
    artifacts.forEach((a,i)=>{const b=document.createElement('button');b.type='button';b.className='artifact-card';b.innerHTML=`<span class="artifact-art">${art(a[5])}</span><span class="artifact-meta">${esc(a[4])}</span><strong>${esc(a[0])}</strong><small>${esc(a[1])}</small>`;b.addEventListener('click',()=>show(i));grid.appendChild(b);});function show(i){selectedIndex=i;const a=artifacts[i];$('[data-museum-art]',root).innerHTML=art(a[5]);$('[data-museum-code]',root).textContent=a[4];$('[data-museum-title]',root).textContent=a[0];$('[data-museum-copy]',root).textContent=a[2];$('[data-museum-note]',root).textContent=a[3];$$('.artifact-card',root).forEach((b,j)=>b.classList.toggle('selected',j===i));const favorite=favorites.includes(i);$('[data-museum-favorite]',root).textContent=favorite?'★ Saved artifact':'☆ Save artifact';$('[data-museum-favorite]',root).setAttribute('aria-pressed',String(favorite));} $('[data-action="museum-random"]',root).addEventListener('click',()=>show(Math.floor(Math.random()*artifacts.length)));$('[data-museum-favorite]',root).addEventListener('click',()=>{if(favorites.includes(selectedIndex))favorites=favorites.filter(i=>i!==selectedIndex);else favorites.push(selectedIndex);try{localStorage.setItem(storageKey,JSON.stringify(favorites));}catch(_){}show(selectedIndex);renderFavorites();});show(0);renderFavorites();return()=>{};}

  // 18 — Dead Interface Archive: a fictional late-90s desktop simulation.
  function deadInterfaceMarkup(){return projectFrame('Strange archive / 02','Dead Interface Archive','A desktop recovered from a machine that was never registered. Open its programs. Some of them remember previous sessions. Your Notes document is saved locally.',`<div class="retro-desktop"><div class="retro-icons">${[['COMPUTER','▣','computer'],['NOTES','▤','notes'],['PAINT','◩','paint'],['MAIL','✉','mail'],['CLOCK','◷','clock'],['TRASH','▱','trash']].map(a=>`<button type="button" class="retro-icon" data-retro-app="${a[2]}"><span>${a[1]}</span><small>${a[0]}</small></button>`).join('')}</div><div class="retro-window" data-retro-window hidden><header><strong data-retro-title>PROGRAM</strong><button type="button" data-retro-close aria-label="Close window">×</button></header><div class="retro-content" data-retro-content></div></div><div class="retro-taskbar"><span>START</span><span data-retro-status>READY</span><span data-retro-clock>14:08</span></div></div>`,panel('System status',`<div class="tool-readout"><span>Operating system</span><strong>Windowglass 98</strong></div><div class="tool-readout"><span>Machine state</span><strong data-retro-state>RUNNING</strong></div><p class="tool-small">This is a simulated desktop. The windows and documents are fictional interface pieces; no files on your computer are opened or changed.</p>${action('Open a random program','retro-random')}`),'A self-contained desktop mock-up inspired by late-1990s interfaces. Its Paint window draws only inside this project.');}
  function bindDead(root){const win=$('[data-retro-window]',root),content=$('[data-retro-content]',root),title=$('[data-retro-title]',root);const noteKey='curioid-dead-interface-notes-v1';let notes='The machine is working as expected.\nDo not remove the quiet setting.\n\nI moved the clock back by one minute. It moved forward again.',timer=null;try{notes=localStorage.getItem(noteKey)||notes;}catch(_){}function open(app){if(timer){clearInterval(timer);timer=null;}win.hidden=false;const data={computer:['My Computer',`<div class="retro-files"><button data-retro-file="system">▣ SYSTEM (C:)</button><button data-retro-file="letters">▤ LETTERS (A:)</button><button data-retro-file="unknown">▧ UNKNOWN (0:)</button></div><p class="retro-small" data-retro-file-note>Choose a drive to inspect it.</p>`],notes:['Untitled - Notes',`<textarea class="retro-notes" data-retro-notes spellcheck="false">${esc(notes)}</textarea><div class="tool-button-row"><button class="tool-button" data-retro-save>Save note</button></div>`],paint:['Paint',`<canvas class="retro-paint" width="520" height="250"></canvas><div class="tool-button-row"><button class="tool-button" data-retro-clear>Clear canvas</button><label class="tool-small">Color <input type="color" data-retro-color value="#d6ff69"></label></div>`],mail:['Inbox',`<div class="retro-mail"><button data-mail="1"><b>Subject: Re: the hallway</b><small>from: building.manager</small></button><button data-mail="2"><b>Subject: Clock correction</b><small>from: system</small></button><button data-mail="3"><b>Subject: You left something open</b><small>from: unknown</small></button></div><p class="retro-small" data-mail-body>Select a message.</p>`],clock:['Clock',`<div class="retro-big-clock" data-retro-big-clock>14:08:00</div><p class="retro-small">The clock is synchronized with your device. It sometimes looks away.</p>`],trash:['Recycle Bin',`<div class="retro-trash">The bin is empty.<br><small>Last emptied: tomorrow, 08:14</small></div>`]};title.textContent=data[app][0];content.innerHTML=data[app][1];if(app==='notes'){const field=$('[data-retro-notes]',content);const saveNote=()=>{notes=field.value;try{localStorage.setItem(noteKey,notes);return true;}catch(_){return false;}};field.addEventListener('input',saveNote);$('[data-retro-save]',content).addEventListener('click',()=>toast(null,saveNote()?'Note saved in this browser.':'Note kept for this visit; browser storage is unavailable.'));}if(app==='computer')$$('[data-retro-file]',content).forEach(b=>b.addEventListener('click',()=>{$('[data-retro-file-note]',content).textContent=({system:'SYSTEM: 3 folders, 14 files, 1 folder marked “not yet”.',letters:'LETTERS: 4 unsent messages and a return address.',unknown:'UNKNOWN: The drive is not installed. It is currently in use.'})[b.dataset.retroFile];}));if(app==='paint'){const c=$('.retro-paint',content),ctx=c.getContext('2d');ctx.fillStyle='#fafafa';ctx.fillRect(0,0,c.width,c.height);let drawing=false;c.addEventListener('pointerdown',e=>{drawing=true;c.setPointerCapture(e.pointerId);const r=c.getBoundingClientRect();ctx.beginPath();ctx.moveTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height);});c.addEventListener('pointermove',e=>{if(!drawing)return;const r=c.getBoundingClientRect();ctx.strokeStyle=$('[data-retro-color]',content).value;ctx.lineWidth=4;ctx.lineCap='round';ctx.lineTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height);ctx.stroke();});c.addEventListener('pointerup',()=>drawing=false);$('[data-retro-clear]',content).addEventListener('click',()=>{ctx.fillStyle='#fafafa';ctx.fillRect(0,0,c.width,c.height);});}if(app==='mail')$$('[data-mail]',content).forEach(b=>b.addEventListener('click',()=>{$('[data-mail-body]',content).textContent=({1:'Please stop leaving the east corridor light on. There is no east corridor.',2:'The clock was corrected. It has asked not to be corrected again.',3:'You left the window open. I am not referring to the computer.'})[b.dataset.mail];}));if(app==='clock'){timer=setInterval(()=>{$('[data-retro-big-clock]',content).textContent=new Date().toLocaleTimeString();},1000);} $('[data-retro-state]',root).textContent='PROGRAM OPEN';}
    $$('[data-retro-app]',root).forEach(b=>b.addEventListener('click',()=>open(b.dataset.retroApp)));$('[data-retro-close]',root).addEventListener('click',()=>{win.hidden=true;if(timer)clearInterval(timer);timer=null;$('[data-retro-state]',root).textContent='RUNNING';});$('[data-action="retro-random"]',root).addEventListener('click',()=>open(pick(['computer','notes','paint','mail','clock','trash'])));$('[data-retro-clock]',root).textContent=new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});return()=>{if(timer)clearInterval(timer);};}

  // 19 — Unbuilt Tomorrow: design proposals from a future that was shelved.
  const futures=[
    ['The Quiet Tram','2041 · Transit','A tram that changes route according to the noise level inside it. The quieter the carriage, the further it travels from the city centre.','Its route map includes one stop called “home”. No passenger has found it twice.'],
    ['Window Orchard','2038 · Housing','A modular apartment facade with growing pockets between the glass panes. Residents can grow herbs without opening a window.','The plants lean toward rooms that are not occupied.'],
    ['Public Shade No. 4','2050 · Civic design','A network of retractable shade sails that follows the sun using a mechanical clockwork system. It is powered by no electricity.','The central sail turns at night, when there is no sun to follow.'],
    ['The Borrowed Lift','2046 · Architecture','A lift that does not travel vertically. It moves the passenger to the nearest room with the same view.','Building inspectors could not agree whether it was a lift or a corridor.'],
    ['Pocket Weather Station','2035 · Domestic devices','A countertop object that reports the weather expected in the room where it is placed.','It occasionally reports weather for a room that has not been built.'],
    ['The Long Bench','2055 · Public furniture','A continuous bench designed to connect separate public squares through underground supports.','The bench is longer than the distance between its published endpoints.']
  ];
  function futureMarkup(){return projectFrame('Strange archive / 03','Unbuilt Tomorrow','A catalogue of prototypes, civic ideas and ordinary future objects that were designed, reviewed and quietly shelved.',`<div class="future-dossier"><div class="future-blueprint" data-future-art><span>PROJECT DRAWING</span><svg viewBox="0 0 360 230" aria-hidden="true"><path d="M25 180h310M60 180V80h70v100m20 0V48h70v132m20 0V95h70v85M30 60h300M45 45v150M315 45v150" fill="none" stroke="#d6ff69" stroke-width="2"/><circle cx="180" cy="48" r="6" fill="#baa7ff"/></svg></div><div class="future-record"><p class="tool-eyebrow" data-future-meta>2041 / TRANSIT</p><h4 data-future-title>The Quiet Tram</h4><p data-future-copy></p><blockquote data-future-note></blockquote></div></div><div class="tool-button-row">${action('← Previous proposal','future-prev')}${action('Next proposal →','future-next',true)}${action('Surprise me','future-random')}</div>`,panel('Archive filters',select('Field','future-field',[['all','All proposals'],['Transit','Transit'],['Housing','Housing'],['Civic design','Civic design'],['Architecture','Architecture'],['Domestic devices','Domestic devices'],['Public furniture','Public furniture']])+`<div class="tool-readout"><span>Proposal status</span><strong>NOT COMMISSIONED</strong></div><p class="tool-small">These are speculative design concepts, not real products or engineering plans. Each one has a detail that was not resolved before shelving.</p>`),'A speculative design archive with fictional proposals and editorial notes.');}
  function bindFuture(root){let index=0,filtered=[0,1,2,3,4,5];function show(){const f=futures[filtered[index%filtered.length]];$('[data-future-meta]',root).textContent=f[1].toUpperCase();$('[data-future-title]',root).textContent=f[0];$('[data-future-copy]',root).textContent=f[2];$('[data-future-note]',root).textContent=f[3];const art=$('[data-future-art] svg',root);art.style.transform=`rotate(${(index%3-1)*1.2}deg)`;art.querySelector('circle').setAttribute('cx',String(120+index*17%120));}function filter(){const field=$('[data-select="future-field"]',root).value;filtered=futures.map((f,i)=>[f,i]).filter(([f])=>field==='all'||f[1].split(' · ')[1]===field).map(x=>x[1]);index=0;show();}function move(n){index=(index+n+filtered.length)%filtered.length;show();}$('[data-action="future-prev"]',root).addEventListener('click',()=>move(-1));$('[data-action="future-next"]',root).addEventListener('click',()=>move(1));$('[data-action="future-random"]',root).addEventListener('click',()=>{index=Math.floor(Math.random()*filtered.length);show();});$('[data-select="future-field"]',root).addEventListener('change',filter);show();return()=>{};}

  // 20 — Color Alchemist: palette generator with contrast information and export.
  function colorMarkup(){return projectFrame('Creative tool / 01','Color Alchemist','Make a palette from one color, then let the relationships do the complicated part. Lock the colors you want to keep.',`<div class="palette-strip" data-palette-strip></div><div class="palette-info" data-palette-info>Five colors · one useful disagreement.</div><div class="tool-button-row">${action('↻ Recompose unlocked colors','palette-shuffle',true)}${action('Copy CSS variables','palette-copy')}${action('Export palette','palette-export')}</div>`,panel('Color recipe',`<label class="tool-control"><span>Starting color</span><input type="color" data-base-color value="#d6ff69"></label>${select('Relationship','harmony',[['analogous','Analogous'],['complement','Complementary'],['triad','Triadic'],['split','Split complementary'],['quiet','Quiet / tonal']])}${range('Variation','variation',0,100,58)}<div class="tool-readout"><span>Text contrast / black</span><strong data-contrast>—</strong></div><p class="tool-small">Click a color to lock it. Locked colors stay in place when you recompose the palette. Contrast figures are calculated from relative luminance.</p>`),'Palette values are local to this project. Copy or export them to reuse in another design.');}
  function bindColor(root){const storageKey='curioid-color-alchemist-palette-v1';let colors=[],locked=[false,false,false,false,false],restored=false;try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&Array.isArray(saved.colors)&&saved.colors.length===5&&Array.isArray(saved.locked)&&saved.locked.length===5){colors=saved.colors;locked=saved.locked.map(Boolean);restored=true;}}catch(_){}const strip=$('[data-palette-strip]',root);function persistPalette(){try{localStorage.setItem(storageKey,JSON.stringify({colors,locked}));}catch(_){}}function hsl(hex){const r=parseInt(hex.slice(1,3),16)/255,g=parseInt(hex.slice(3,5),16)/255,b=parseInt(hex.slice(5,7),16)/255,max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=0,s=0,l=(max+min)/2;if(d){s=d/(1-Math.abs(2*l-1));switch(max){case r:h=((g-b)/d)%6;break;case g:h=(b-r)/d+2;break;default:h=(r-g)/d+4;}h*=60;if(h<0)h+=360;}return[h,s,l];}function hex(h,s,l){s=clamp(s,0,1);l=clamp(l,0,1);const c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2;let [r,g,b]=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+[r,g,b].map(v=>Math.round((v+m)*255).toString(16).padStart(2,'0')).join('');}function luminance(c){const v=c.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:Math.pow((x+.055)/1.055,2));return .2126*v[0]+.7152*v[1]+.0722*v[2];}function ratio(a,b){const x=luminance(a),y=luminance(b);return ((Math.max(x,y)+.05)/(Math.min(x,y)+.05)).toFixed(2)+':1';}
    function compose(){const base=hsl($('[data-base-color]',root).value),mode=$('[data-select="harmony"]',root).value,v=+$('[data-range="variation"]',root).value/100;const offsets=mode==='analogous'?[-42,-20,0,20,42]:mode==='complement'?[-15,0,0,180,195]:mode==='triad'?[0,120,240,12,132]:mode==='split'?[-150,-25,0,25,150]:[-8,-4,0,4,8];colors=offsets.map((o,i)=>locked[i]&&colors[i]?colors[i]:hex((base[0]+o+360)%360,base[1]*(.55+v*.65),clamp(base[2]+(i-2)*(.08+v*.13),.18,.84)));render();}function render(){strip.innerHTML='';colors.forEach((c,i)=>{const b=document.createElement('button');b.type='button';b.className='palette-swatch'+(locked[i]?' locked':'');b.style.background=c;b.innerHTML=`<span>${c.toUpperCase()}</span><i>${locked[i]?'LOCKED':'LOCK'}</i>`;b.addEventListener('click',()=>{locked[i]=!locked[i];render();persistPalette();});strip.appendChild(b);});persistPalette();$('[data-contrast]',root).textContent=ratio(colors[2]||'#d6ff69','#000000');$('[data-palette-info]',root).textContent=`${colors.length} colors · ${locked.filter(Boolean).length} locked · ${$('[data-select="harmony"]',root).selectedOptions[0].textContent}`;}
    $('[data-action="palette-shuffle"]',root).addEventListener('click',compose);$('[data-action="palette-copy"]',root).addEventListener('click',async()=>{const txt=colors.map((c,i)=>`--curioid-${i+1}: ${c};`).join('\n');try{await navigator.clipboard.writeText(txt);toast(null,'CSS variables copied.');}catch(e){downloadBlob(new Blob([txt],{type:'text/css'}),'curioid-palette.css');}});$('[data-action="palette-export"]',root).addEventListener('click',()=>downloadBlob(new Blob([JSON.stringify({colors,locked},null,2)],{type:'application/json'}),'curioid-palette.json'));$('[data-base-color]',root).addEventListener('input',compose);$('[data-select="harmony"]',root).addEventListener('change',compose);$('[data-range="variation"]',root).addEventListener('input',compose);if(restored)render();else compose();return()=>{};}

  // 21 — Type Foundry: a typography poster creator.
  function typeMarkup(){return projectFrame('Creative tool / 02','Type Foundry','Set a phrase, give it a voice and build a small typographic specimen. A poster maker for words that want to look slightly out of place.',`<div class="type-poster-wrap"><canvas class="tool-canvas type-canvas" aria-label="Typography poster preview"></canvas></div><div class="tool-button-row">${action('New composition','type-random',true)}${action('↓ Export poster','type-export')}</div>`,panel('Type controls',`<label class="tool-control"><span>Main phrase</span><input type="text" data-type-main maxlength="40" value="THE QUIET PART"></label><label class="tool-control"><span>Small line</span><input type="text" data-type-sub maxlength="70" value="A STUDY IN ALMOST SAYING IT"></label>${select('Typeface','type-font',[['sans','Modern sans'],['serif','Editorial serif'],['mono','Monospace'],['condensed','Condensed bold']])}${select('Composition','type-layout',[['stack','Stacked'],['split','Split field'],['orbit','Orbiting'],['poster','Classic poster']])}${range('Scale','type-scale',30,100,74)}${range('Distortion','type-distort',0,100,28)}<label class="tool-control"><span>Accent color</span><input type="color" data-type-color value="#d6ff69"></label><p class="tool-small">Use your own words. The preview is drawn locally and exported as a PNG.</p>`),'The poster is rendered with system fonts, so no font files are downloaded or embedded.');}
  function bindType(root){const canvas=$('.type-canvas',root);function draw(target=canvas){const isPreview=target===canvas,w=isPreview?(canvas.clientWidth||800):1600,h=isPreview?(canvas.clientHeight||500):1000,dpr=isPreview?Math.min(2,devicePixelRatio||1):1;target.width=Math.round(w*dpr);target.height=Math.round(h*dpr);const ctx=target.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#191923';ctx.fillRect(0,0,w,h);const main=$('[data-type-main]',root).value||' ',sub=$('[data-type-sub]',root).value||'',font=$('[data-select="type-font"]',root).value,layout=$('[data-select="type-layout"]',root).value,scale=+$('[data-range="type-scale"]',root).value/100,dist=+$('[data-range="type-distort"]',root).value/100,color=$('[data-type-color]',root).value;ctx.save();ctx.translate(w/2,h/2);ctx.rotate(dist*.035);ctx.fillStyle='#dcdbe2';ctx.strokeStyle=color;ctx.textAlign='center';ctx.textBaseline='middle';const family=font==='serif'?'Georgia,serif':font==='mono'?'ui-monospace,monospace':'system-ui,sans-serif',weight=font==='condensed'?'1000':'900',size=Math.min(w*.13,105)*scale;ctx.font=`${weight} ${size}px ${family}`;ctx.shadowColor=color+'44';ctx.shadowBlur=dist*.28;ctx.globalAlpha=.94;if(layout==='split'){ctx.textAlign='left';ctx.fillStyle=color;ctx.fillText(main.slice(0,Math.ceil(main.length/2)), -w*.4,-20,w*.78);ctx.fillStyle='#eee';ctx.fillText(main.slice(Math.ceil(main.length/2)), -w*.4,size*.9,w*.78);}else if(layout==='orbit'){ctx.font=`${weight} ${size*.72}px ${family}`;ctx.strokeText(main,-w*.43,0,w*.86);ctx.fillStyle=color;ctx.fillText(main,-w*.42,0,w*.84);}else{const words=main.toUpperCase().split(' ');const max=Math.max(...words.map(x=>x.length));const fsize=Math.min(size,w*.82/(max*.58));ctx.font=`${weight} ${fsize}px ${family}`;words.forEach((word,i)=>{ctx.fillStyle=i%2?color:'#eee';const y=(i-(words.length-1)/2)*fsize*.95;let hash=2166136261;for(let k=0;k<word.length;k++)hash=Math.imul(hash^word.charCodeAt(k),16777619);const jitter=dist*((hash>>>0)%25-12);ctx.fillText(word,jitter,y,w*.86);});}ctx.globalAlpha=1;ctx.shadowBlur=0;ctx.fillStyle=color;ctx.fillRect(-w*.4,h*.22,w*.8,2);ctx.fillStyle='#aaa8b3';ctx.font='10px ui-monospace,monospace';ctx.textAlign='left';ctx.fillText(sub.toUpperCase(),-w*.4,h*.27,w*.8);ctx.textAlign='right';ctx.fillStyle='#777582';ctx.fillText('CURIOID / TYPE STUDY',w*.4,h*.37);ctx.restore();}const ro=new ResizeObserver(()=>draw());ro.observe(canvas);['[data-type-main]','[data-type-sub]','[data-select="type-font"]','[data-select="type-layout"]','[data-range="type-scale"]','[data-range="type-distort"]','[data-type-color]'].forEach(s=>$(s,root).addEventListener('input',()=>draw()));$('[data-select="type-font"]',root).addEventListener('change',()=>draw());$('[data-select="type-layout"]',root).addEventListener('change',()=>draw());$('[data-action="type-random"]',root).addEventListener('click',()=>{const phrases=['SOMETHING IS MISSING','PLEASE REMAIN HERE','A VERY SMALL DISTANCE','THE ROOM WAS READY','WE HAVE ALWAYS BEEN OPEN','NOTHING TO REPORT'];$('[data-type-main]',root).value=pick(phrases);$('[data-type-color]',root).value=pick(['#d6ff69','#baa7ff','#ff9cba','#85e6da']);draw();});$('[data-action="type-export"]',root).addEventListener('click',()=>{const exportCanvas=document.createElement('canvas');draw(exportCanvas);saveCanvas(exportCanvas,'type-foundry-poster-1600x1000.png');});draw();return()=>ro.disconnect();}

  // 22 — Idea Tumbler: combine prompts into a usable project seed.
  const ideaSubjects=['a closed aquarium','a public clock','a vending machine','an abandoned sports hall','a forgotten computer','a miniature railway','a household object','a quiet airport','an unmarked doorway','a weather station','a community noticeboard','a temporary museum'];
  const ideaActions=['keeps a record of visitors','changes one detail each morning','responds to a sound nobody makes','only works when ignored','creates a map of nearby memories','repeats a task with tiny mistakes','offers an instruction that changes','stores things that were never placed inside'];
  const ideaFormats=['a browser experience','a tiny game','a generative artwork','a fictional archive','a short interactive story','a useful creative tool','a sound experiment'];
  const ideaLimits=['using only one button','with no written explanation','that lasts less than two minutes','built from simple geometric shapes','with one rule that changes halfway through','that can be understood without sound','with a single fixed camera'];
  const ideaDetails=['the interface is one minute ahead','the result looks almost correct','the last visitor is listed twice','the smallest element is the most important','one object is always facing away','the help text refers to a different project','nothing is broken, according to the status light'];
  function tumblerMarkup(){return projectFrame('Creative tool / 03','Idea Tumbler','Combine a subject, a behavior and a constraint. The result is a starting point, not a brief you have to obey.',`<div class="idea-output"><p class="tool-eyebrow">PROJECT SEED / <span data-idea-number>001</span></p><h4 data-idea-title>The place that keeps a record</h4><p data-idea-pitch>A closed aquarium keeps a record of visitors through a browser experience, using only one button. The result looks almost correct.</p><div class="idea-specs"><div><small>FORMAT</small><strong data-idea-format>Browser experience</strong></div><div><small>RULE</small><strong data-idea-limit>One button</strong></div><div><small>FIRST BUILD</small><strong data-idea-first>One screen, one action, one surprising result.</strong></div></div></div><div class="tool-button-row">${action('↻ Tumble ideas','idea-tumble',true)}${action('＋ Save this seed','idea-save')}${action('Copy project seed','idea-copy')}</div><div class="saved-ideas" data-idea-saved></div>`,panel('Tumbler settings',select('Creative direction','idea-direction',[['any','Anything goes'],['interactive','Interactive / web'],['game','Tiny game'],['visual','Visual art'],['sound','Sound & motion'],['archive','Archive / fiction'],['tool','Creative tool']])+range('Strangeness','idea-strange',0,100,68)+`<p class="tool-small">Saved seeds stay in this browser. Export or copy any result to continue developing it elsewhere.</p>`),'Idea combinations are generated from a curated local word bank. No prompt is sent to an AI service.');}
  function bindTumbler(root){
    const storageKey='curioid-idea-seeds-v1';
    let n=1,current=null,saved=[];
    try{
      const restored=JSON.parse(window.localStorage.getItem(storageKey)||'[]');
      if(Array.isArray(restored)){
        saved=restored.filter(item=>item&&typeof item.title==='string'&&typeof item.pitch==='string').slice(0,12);
        n=Math.max(1,...saved.map(item=>(Number(item.n)||0)+1));
      }
    }catch(error){/* Storage can be unavailable in private or restricted contexts. */}
    function persist(){
      try{window.localStorage.setItem(storageKey,JSON.stringify(saved));return true;}
      catch(error){return false;}
    }
    function tumble(){
      const direction=$('[data-select="idea-direction"]',root).value;
      const strange=+$('[data-range="idea-strange"]',root).value/100;
      let subject=pick(ideaSubjects),verb=pick(ideaActions);
      const format=direction==='any'?pick(ideaFormats):({interactive:'a browser experience',game:'a tiny game',visual:'a generative artwork',sound:'a sound experiment',archive:'a fictional archive',tool:'a useful creative tool'}[direction]);
      const limit=pick(ideaLimits),detail=pick(ideaDetails);
      if(strange<.35)subject=pick(['a kitchen timer','a small garden','a public bench','a paper map','a desk lamp']);
      const title=subject.split(' ').slice(-2).map(x=>x[0].toUpperCase()+x.slice(1)).join(' ')+' / '+pick(['Index','Room','Protocol','Study','No. '+String(n).padStart(2,'0')]);
      const pitch=`${subject} ${verb} through ${format}, ${limit}. ${strange>.5?detail+'.':'Keep the interaction clear and let the unusual detail emerge slowly.'}`;
      $('[data-idea-number]',root).textContent=String(n).padStart(3,'0');
      $('[data-idea-title]',root).textContent=title;
      $('[data-idea-pitch]',root).textContent=pitch;
      $('[data-idea-format]',root).textContent=format;
      $('[data-idea-limit]',root).textContent=limit.replace(/^using /,'');
      $('[data-idea-first]',root).textContent='Build one screen, one action and one complete result.';
      current={n,title,pitch,format,limit,detail};n++;
    }
    function renderSaved(){
      const box=$('[data-idea-saved]',root);
      box.innerHTML=saved.length?'<strong>Saved seeds</strong>'+saved.map((item,i)=>`<button type="button" data-seed="${i}">${esc(item.title)}</button>`).join(''):'<span>No saved seeds yet.</span>';
      $$('[data-seed]',box).forEach(button=>button.addEventListener('click',()=>{
        const item=saved[+button.dataset.seed];
        $('[data-idea-number]',root).textContent=String(item.n||0).padStart(3,'0');
        $('[data-idea-title]',root).textContent=item.title;
        $('[data-idea-pitch]',root).textContent=item.pitch;
        $('[data-idea-format]',root).textContent=item.format||'Saved idea';
        $('[data-idea-limit]',root).textContent=(item.limit||'').replace(/^using /,'');
        current=item;
      }));
    }
    function serialize(){return current?`${current.title}\n${current.pitch}\nFormat: ${current.format}\nConstraint: ${current.limit}`:'';}
    $('[data-action="idea-tumble"]',root).addEventListener('click',tumble);
    $('[data-action="idea-save"]',root).addEventListener('click',()=>{
      if(!current)return;
      if(saved.some(item=>item.title===current.title&&item.pitch===current.pitch)){toast(null,'This seed is already saved.');return;}
      saved.unshift({...current});saved=saved.slice(0,12);
      const savedToBrowser=persist();renderSaved();
      toast(null,savedToBrowser?'Project seed saved in this browser.':'Saved for this session; browser storage is unavailable.');
    });
    $('[data-action="idea-copy"]',root).addEventListener('click',async()=>{
      try{await navigator.clipboard.writeText(serialize());toast(null,'Project seed copied.');}
      catch(error){downloadBlob(new Blob([serialize()],{type:'text/plain'}),'curioid-project-seed.txt');}
    });
    $('[data-select="idea-direction"]',root).addEventListener('change',tumble);
    $('[data-range="idea-strange"]',root).addEventListener('input',()=>{});
    tumble();renderSaved();return()=>{};
  }

  const modules={
    'gravity-garden':[gravityMarkup,bindGravity], 'pattern-engine':[patternMarkup,bindPattern], 'echo-cabinet':[echoMarkup,bindEcho], 'impossible-objects':[impossibleMarkup,bindImpossible], 'pixel-weather':[weatherMarkup,bindWeather], 'dream-index':[dreamMarkup,bindDream],
    'chromatic-fossils':[chromaticMarkup,bindChromatic], 'organic-errors':[organicMarkup,bindOrganic], 'afterimage-studio':[afterimageMarkup,bindAfterimage],
    'pocket-universe':[pocketMarkup,bindPocket], 'one-button-ritual':[ritualMarkup,bindRitual], 'last-corridor':[corridorMarkup,bindCorridor],
    'frequency-garden':[frequencyMarkup,bindFrequency], 'motion-residue':[motionMarkup,bindMotion], 'noise-choir':[choirMarkup,bindChoir],
    'museum-almost':[museumMarkup,bindMuseum], 'dead-interface':[deadInterfaceMarkup,bindDead], 'unbuilt-tomorrow':[futureMarkup,bindFuture],
    'color-alchemist':[colorMarkup,bindColor], 'type-foundry':[typeMarkup,bindType], 'idea-tumbler':[tumblerMarkup,bindTumbler]
  };
  window.CurioidProjects={
    ids:Object.keys(modules),
    mount(id,host,api={}){
      const item=modules[id];if(!item){host.innerHTML='<div class="project-unavailable">This project is not available in this build.</div>';return()=>{};}
      host.innerHTML=item[0]();
      restoreProjectPreferences(host,id);
      bindRanges(host);
      try {
        const moduleCleanup = item[1](host,api) || (()=>{});
        const utilityCleanup = bindProjectUtilities(host,id,api);
        return () => { try { utilityCleanup(); } finally { moduleCleanup(); } };
      } catch(error) {
        console.error('CURIOID project failed:',id,error);
        host.innerHTML='<div class="project-error"><strong>This project encountered a problem.</strong><p>Close this window and open it again. The rest of CURIOID is unaffected.</p></div>';
        return()=>{};
      }
    }
  };
})();
